tool_schemas.implementation:
def maps_regeocode(location, radius=None, extensions=None, output=None, poitype=None, roadlevel=None, homeorcorp=None, batch=None, **_extra):
    import json, os, datetime, time, hashlib, random, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            return dt.replace(microsecond=0).isoformat() + "Z"
        return None

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _align_window(dt, granularity):
        if granularity == "minute":
            return dt.replace(second=0, microsecond=0)
        if granularity == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if granularity == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if granularity == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha1((str(time.time_ns()) + '|' + str(random.random())).encode('utf-8')).hexdigest()[:16]}"

    def _record_call(tool_calls, tenant_id, api_key_id, provider_key_id, status, request_params, normalized_params=None,
                     cache_key=None, cache_ttl_seconds=None, http_status=None, provider_endpoint=None,
                     provider_request_id=None, response_body=None, error_code=None, error_message=None, duration_ms=None, billed_units=1):
        tc_id = _new_id("tc")
        row = {
            "id": tc_id,
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "provider_key_id": provider_key_id,
            "mcp_session_id": None,
            "tool_name": "maps_regeocode",
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "normalized_params": normalized_params,
            "cache_key": cache_key,
            "cache_ttl_seconds": cache_ttl_seconds,
            "http_status": http_status,
            "provider_endpoint": provider_endpoint,
            "provider_request_id": provider_request_id,
            "response_body": response_body,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "billed_units": int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        tool_calls.append(row)
        return row

    def _transition(row, new_status):
        transitions = {
            "received": ["validated", "failed", "rate_limited"],
            "validated": ["cache_hit", "dispatched", "failed", "rate_limited"],
            "cache_hit": ["succeeded"],
            "dispatched": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
            "rate_limited": []
        }
        cur = row.get("status")
        if new_status == cur:
            return True
        if cur not in transitions or new_status not in transitions[cur]:
            return False
        row["status"] = new_status
        row["updated_at"] = now_iso
        return True

    def _upsert_rollup(usage, tenant_id, api_key_id, tool_name, granularity, window_start, delta_requests=0,
                       delta_success=0, delta_error=0, delta_rl=0, delta_billed=0):
        # unique(tenant_id, api_key_id, tool_name, window_granularity, window_start)
        ws_iso = window_start.replace(microsecond=0).isoformat() + "Z"
        match = None
        for r in usage:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == granularity and r.get("window_start") == ws_iso:
                match = r
                break
        if match is None:
            match = {
                "id": _new_id("ur"),
                "tenant_id": tenant_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "window_start": ws_iso,
                "window_granularity": granularity,
                "requests_count": 0,
                "success_count": 0,
                "error_count": 0,
                "rate_limited_count": 0,
                "billed_units": 0,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            usage.append(match)
        def _inc(k, dv):
            if dv:
                match[k] = int(match.get(k) or 0) + int(dv)
        _inc("requests_count", delta_requests)
        _inc("success_count", delta_success)
        _inc("error_count", delta_error)
        _inc("rate_limited_count", delta_rl)
        _inc("billed_units", delta_billed)
        match["updated_at"] = now_iso
        # integrity clamp
        for k in ("requests_count", "success_count", "error_count", "rate_limited_count", "billed_units"):
            try:
                if match[k] < 0:
                    match[k] = 0
            except Exception:
                match[k] = 0
        if (match["success_count"] + match["error_count"] + match["rate_limited_count"]) > match["requests_count"]:
            match["requests_count"] = match["success_count"] + match["error_count"] + match["rate_limited_count"]
        return match

    def _sum_rollups(usage, tenant_id, api_key_id, tool_name, granularity, window_start):
        ws_iso = window_start.replace(microsecond=0).isoformat() + "Z"
        total = 0
        for r in usage:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == granularity and r.get("window_start") == ws_iso:
                total += int(r.get("requests_count") or 0)
        return total

    def _normalize_location(s):
        # returns list of "lng,lat" strings
        if not isinstance(s, str) or not s.strip():
            return None, "location 不能为空"
        parts = [p.strip() for p in s.split("|")] if batch else [s.strip()]
        if batch and len(parts) == 0:
            return None, "batch=true 时 location 列表不能为空"
        out = []
        for p in parts:
            if not p:
                return None, "location 列表包含空项"
            m = re.match(r"^\s*(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)\s*$", p)
            if not m:
                return None, f"location 格式非法: {p}"
            lng = float(m.group(1))
            lat = float(m.group(2))
            if not (-180.0 <= lng <= 180.0 and -90.0 <= lat <= 90.0):
                return None, f"location 超出范围: {p}"
            out.append(f"{lng:.6f},{lat:.6f}")
        return out, None

    # --- validate inputs ---
    if not isinstance(location, str):
        return _err("VALIDATION_ERROR", "location 必须为 string")
    if radius is not None and not isinstance(radius, int):
        return _err("VALIDATION_ERROR", "radius 必须为 integer")
    if radius is not None and radius < 0:
        return _err("VALIDATION_ERROR", "radius 必须 >= 0")
    if extensions is not None:
        if not isinstance(extensions, str) or extensions not in ("base", "all"):
            return _err("VALIDATION_ERROR", "extensions 枚举非法", allowed=["base", "all"])
    if output is not None:
        if not isinstance(output, str) or output not in ("JSON", "XML"):
            return _err("VALIDATION_ERROR", "output 枚举非法", allowed=["JSON", "XML"])
    if poitype is not None and not isinstance(poitype, str):
        return _err("VALIDATION_ERROR", "poitype 必须为 string")
    if roadlevel is not None:
        if not isinstance(roadlevel, int) or roadlevel not in (0, 1):
            return _err("VALIDATION_ERROR", "roadlevel 枚举非法", allowed=[0, 1])
    if homeorcorp is not None:
        if not isinstance(homeorcorp, int) or homeorcorp not in (0, 1):
            return _err("VALIDATION_ERROR", "homeorcorp 枚举非法", allowed=[0, 1])
    if batch is not None and not isinstance(batch, bool):
        return _err("VALIDATION_ERROR", "batch 必须为 boolean")

    # --- load store ---
    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    pkeys = _load("amap_provider_keys.json")
    tool_calls = _load("tool_calls.json")
    usage = _load("usage_rollups.json")

    # --- resolve ambient auth: pick a working tenant + api key + provider key (if needed) ---
    active_tenants = [t for t in tenants if t.get("status") == "active"]
    if not active_tenants:
        # still must log call if possible? no tenant available -> unauthorized
        return _err("UNAUTHORIZED", "无可用租户上下文")

    # Find any active api_key under an active tenant to enforce per-key minute limit. If none, allow tenant-only usage.
    chosen_tenant = None
    chosen_api_key = None
    for t in active_tenants:
        aks = [k for k in api_keys if k.get("tenant_id") == t.get("id") and k.get("status") == "active"]
        if aks:
            chosen_tenant = t
            chosen_api_key = aks[0]
            break
    if chosen_tenant is None:
        chosen_tenant = active_tenants[0]

    tenant_id = chosen_tenant.get("id")
    api_key_id = chosen_api_key.get("id") if chosen_api_key else None

    # tenant status restriction (only create tool_calls when tenant active)
    if chosen_tenant.get("status") in ("suspended", "deleted"):
        # should not happen because we chose active, but keep rule
        return _err("UNAUTHORIZED", "租户不可用")

    request_params = {
        "location": location,
        "radius": radius,
        "extensions": extensions,
        "output": output,
        "poitype": poitype,
        "roadlevel": roadlevel,
        "homeorcorp": homeorcorp,
        "batch": batch
    }

    tc = _record_call(
        tool_calls, tenant_id, api_key_id, None,
        "received", request_params, normalized_params=None,
        billed_units=1
    )

    # helper to finalize call with status + rollups + persist
    def _finalize(status, response_body=None, error_code=None, error_message=None, http_status=None, provider_key_id=None, provider_endpoint=None, cache_key=None, cache_ttl_seconds=None):
        # enforce integrity rule: response only on succeeded; errors only on failed/rate_limited
        if status == "succeeded":
            tc["response_body"] = response_body if response_body is not None else {}
            tc["error_code"] = None
            tc["error_message"] = None
        else:
            tc["response_body"] = None
            tc["error_code"] = error_code
            tc["error_message"] = error_message
        tc["http_status"] = http_status
        tc["provider_key_id"] = provider_key_id
        tc["provider_endpoint"] = provider_endpoint
        tc["cache_key"] = cache_key
        tc["cache_ttl_seconds"] = cache_ttl_seconds
        tc["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        tc["updated_at"] = now_iso

        # rollups: always count a request (whether succeeded/failed/rate_limited)
        minute_ws = _align_window(now, "minute")
        day_ws = _align_window(now, "day")
        month_ws = _align_window(now, "month")

        _upsert_rollup(usage, tenant_id, api_key_id, "maps_regeocode", "minute", minute_ws, delta_requests=1,
                       delta_success=1 if status == "succeeded" else 0,
                       delta_error=1 if status == "failed" else 0,
                       delta_rl=1 if status == "rate_limited" else 0,
                       delta_billed=tc.get("billed_units") or 0)
        # tenant-level rollups (api_key_id None, tool_name None for all tools)
        _upsert_rollup(usage, tenant_id, None, None, "day", day_ws, delta_requests=1,
                       delta_success=1 if status == "succeeded" else 0,
                       delta_error=1 if status == "failed" else 0,
                       delta_rl=1 if status == "rate_limited" else 0,
                       delta_billed=tc.get("billed_units") or 0)
        _upsert_rollup(usage, tenant_id, None, None, "month", month_ws, delta_requests=1,
                       delta_success=1 if status == "succeeded" else 0,
                       delta_error=1 if status == "failed" else 0,
                       delta_rl=1 if status == "rate_limited" else 0,
                       delta_billed=tc.get("billed_units") or 0)

        # persist
        _save("tool_calls.json", tool_calls)
        _save("usage_rollups.json", usage)

    # validate + normalize -> tc transitions
    if not _transition(tc, "validated"):
        _finalize("failed", error_code="INVALID_TRANSITION", error_message="状态机错误", http_status=500)
        return _err("INVALID_TRANSITION", "状态机错误")

    loc_list, loc_err = _normalize_location(location)
    if loc_err:
        _transition(tc, "failed")
        _finalize("failed", error_code="INVALID_PARAMS", error_message=loc_err, http_status=400)
        return _err("VALIDATION_ERROR", loc_err)

    norm = {
        "locations": loc_list,
        "radius": radius,
        "extensions": extensions or "base",
        "output": output or "JSON",
        "poitype": poitype.strip() if isinstance(poitype, str) else None,
        "roadlevel": roadlevel,
        "homeorcorp": homeorcorp,
        "batch": bool(batch) if batch is not None else False
    }
    # cache key required when normalized_params generated
    cache_key = hashlib.sha1(("maps_regeocode|" + json.dumps(norm, ensure_ascii=False, sort_keys=True)).encode("utf-8")).hexdigest()
    tc["normalized_params"] = norm
    tc["cache_key"] = cache_key
    tc["updated_at"] = now_iso

    # enforce quotas / rate limits BEFORE processing
    minute_ws = _align_window(now, "minute")
    day_ws = _align_window(now, "day")
    month_ws = _align_window(now, "month")

    if chosen_api_key:
        rpm = int(chosen_api_key.get("requests_per_minute_limit") or 0)
        if rpm >= 0 and _sum_rollups(usage, tenant_id, api_key_id, "maps_regeocode", "minute", minute_ws) >= rpm:
            _transition(tc, "rate_limited")
            _finalize("rate_limited", error_code="RATE_LIMITED", error_message="超出 API Key 每分钟限流", http_status=429)
            return _err("RATE_LIMIT", "超出 API Key 每分钟限流", limit_per_minute=rpm)

    daily_quota = int(chosen_tenant.get("daily_request_quota") or 0)
    monthly_quota = int(chosen_tenant.get("monthly_request_quota") or 0)
    day_used = 0
    month_used = 0
    for r in usage:
        if r.get("tenant_id") == tenant_id and r.get("api_key_id") is None and r.get("tool_name") is None:
            if r.get("window_granularity") == "day" and r.get("window_start") == (day_ws.isoformat() + "Z"):
                day_used += int(r.get("requests_count") or 0)
            if r.get("window_granularity") == "month" and r.get("window_start") == (month_ws.isoformat() + "Z"):
                month_used += int(r.get("requests_count") or 0)
    if daily_quota >= 0 and day_used >= daily_quota:
        _transition(tc, "rate_limited")
        _finalize("rate_limited", error_code="QUOTA_EXCEEDED", error_message="超出租户每日配额", http_status=429)
        return _err("QUOTA_EXCEEDED", "超出租户每日配额", daily_request_quota=daily_quota)
    if monthly_quota >= 0 and month_used >= monthly_quota:
        _transition(tc, "rate_limited")
        _finalize("rate_limited", error_code="QUOTA_EXCEEDED", error_message="超出租户每月配额", http_status=429)
        return _err("QUOTA_EXCEEDED", "超出租户每月配额", monthly_request_quota=monthly_quota)

    # cache lookup: find previous succeeded with same cache_key and still within ttl
    cached = None
    for prev in reversed(tool_calls):
        if prev.get("tool_name") == "maps_regeocode" and prev.get("tenant_id") == tenant_id and prev.get("cache_key") == cache_key and prev.get("status") == "succeeded":
            ttl = prev.get("cache_ttl_seconds")
            created_prev = _parse_iso(prev.get("created_at"))
            if isinstance(ttl, int) and ttl >= 0 and created_prev:
                if (now - created_prev).total_seconds() <= ttl:
                    cached = prev
                    break
    if cached is not None:
        if not _transition(tc, "cache_hit"):
            _transition(tc, "failed")
            _finalize("failed", error_code="INVALID_TRANSITION", error_message="缓存命中状态流转失败", http_status=500)
            return _err("INVALID_TRANSITION", "缓存命中状态流转失败")
        if not _transition(tc, "succeeded"):
            _transition(tc, "failed")
            _finalize("failed", error_code="INVALID_TRANSITION", error_message="缓存命中后完成状态流转失败", http_status=500)
            return _err("INVALID_TRANSITION", "缓存命中后完成状态流转失败")
        _finalize("succeeded", response_body=cached.get("response_body") or {}, http_status=200, cache_key=cache_key, cache_ttl_seconds=cached.get("cache_ttl_seconds"))
        return {"data": tc["response_body"], "meta": {"cached": True, "tool_call_id": tc["id"]}}

    # choose provider key (must be same tenant, active)
    candidates = [k for k in pkeys if k.get("tenant_id") == tenant_id and k.get("status") == "active" and isinstance(k.get("weight"), int) and k.get("weight") >= 0]
    if not candidates:
        _transition(tc, "failed")
        _finalize("failed", error_code="UNAUTHORIZED", error_message="无可用高德 provider key", http_status=401)
        return _err("UNAUTHORIZED", "无可用高德 provider key")

    # weighted random selection
    total_w = sum((k.get("weight") or 0) for k in candidates)
    if total_w <= 0:
        chosen_pk = candidates[0]
    else:
        r = random.uniform(0, total_w)
        upto = 0.0
        chosen_pk = candidates[0]
        for k in candidates:
            upto += float(k.get("weight") or 0)
            if r <= upto:
                chosen_pk = k
                break

    # dispatch (simulate upstream, offline)
    if not _transition(tc, "dispatched"):
        _transition(tc, "failed")
        _finalize("failed", error_code="INVALID_TRANSITION", error_message="dispatched 状态流转失败", http_status=500)
        return _err("INVALID_TRANSITION", "dispatched 状态流转失败")

    # Simulated response: deterministic-ish based on cache_key
    results = []
    for loc in loc_list:
        lng_s, lat_s = loc.split(",")
        lng = float(lng_s)
        lat = float(lat_s)
        h = hashlib.sha1((cache_key + "|" + loc).encode("utf-8")).hexdigest()
        adcode = str(int(h[:6], 16) % 900000 + 100000)
        province = "北京市" if adcode.startswith("11") else "中国"
        city = "北京市" if province == "北京市" else ""
        district = ""
        formatted = f"{province}{city}{district}".strip() or "中国"
        item = {
            "location": loc,
            "regeocode": {
                "formatted_address": formatted,
                "addressComponent": {
                    "province": province,
                    "city": city,
                    "district": district,
                    "adcode": adcode,
                    "township": "",
                    "neighborhood": {"name": "", "type": ""},
                    "building": {"name": "", "type": ""},
                    "streetNumber": {"street": "", "number": "", "location": loc, "direction": "", "distance": ""}
                }
            }
        }
        if (extensions or "base") == "all":
            item["regeocode"]["pois"] = []  # offline: no POI dataset
        results.append(item)

    response = {
        "count": len(results),
        "results": results
    }

    # default TTL
    ttl = 3600
    tc["cache_ttl_seconds"] = ttl

    # update api_key last_used_at on success
    if chosen_api_key:
        chosen_api_key["last_used_at"] = now_iso
        chosen_api_key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    if not _transition(tc, "succeeded"):
        _transition(tc, "failed")
        _finalize("failed", error_code="INVALID_TRANSITION", error_message="succeeded 状态流转失败", http_status=500, provider_key_id=chosen_pk.get("id"), provider_endpoint="amap/regeo")
        return _err("INVALID_TRANSITION", "succeeded 状态流转失败")

    _finalize("succeeded", response_body=response, http_status=200, provider_key_id=chosen_pk.get("id"), provider_endpoint="amap/regeo", cache_key=cache_key, cache_ttl_seconds=ttl)
    return {"data": response, "meta": {"cached": False, "tool_call_id": tc["id"]}}

def maps_geo(address, city=None, output=None, batch=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _align_window(dt, granularity):
        if granularity == "minute":
            return dt.replace(second=0, microsecond=0)
        if granularity == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if granularity == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _new_id(prefix):
        import time as _t, random as _r
        return f"{prefix}_{hashlib.sha1((str(_t.time_ns()) + '|' + str(_r.random())).encode('utf-8')).hexdigest()[:16]}"

    def _record_call(tool_calls, tenant_id, api_key_id, provider_key_id, status, request_params, normalized_params=None,
                     cache_key=None, cache_ttl_seconds=None, http_status=None, provider_endpoint=None,
                     response_body=None, error_code=None, error_message=None, billed_units=1):
        tc_id = _new_id("tc")
        row = {
            "id": tc_id,
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "provider_key_id": provider_key_id,
            "mcp_session_id": None,
            "tool_name": "maps_geo",
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "normalized_params": normalized_params,
            "cache_key": cache_key,
            "cache_ttl_seconds": cache_ttl_seconds,
            "http_status": http_status,
            "provider_endpoint": provider_endpoint,
            "provider_request_id": None,
            "response_body": response_body,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": None,
            "billed_units": int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        tool_calls.append(row)
        return row

    def _transition(row, new_status):
        transitions = {
            "received": ["validated", "failed", "rate_limited"],
            "validated": ["cache_hit", "dispatched", "failed", "rate_limited"],
            "cache_hit": ["succeeded"],
            "dispatched": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
            "rate_limited": []
        }
        cur = row.get("status")
        if new_status == cur:
            return True
        if cur not in transitions or new_status not in transitions[cur]:
            return False
        row["status"] = new_status
        row["updated_at"] = now_iso
        return True

    def _upsert_rollup(usage, tenant_id, api_key_id, tool_name, granularity, window_start, delta_requests=0,
                       delta_success=0, delta_error=0, delta_rl=0, delta_billed=0):
        ws_iso = window_start.replace(microsecond=0).isoformat() + "Z"
        match = None
        for r in usage:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == granularity and r.get("window_start") == ws_iso:
                match = r
                break
        if match is None:
            match = {
                "id": _new_id("ur"),
                "tenant_id": tenant_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "window_start": ws_iso,
                "window_granularity": granularity,
                "requests_count": 0,
                "success_count": 0,
                "error_count": 0,
                "rate_limited_count": 0,
                "billed_units": 0,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            usage.append(match)
        def _inc(k, dv):
            if dv:
                match[k] = int(match.get(k) or 0) + int(dv)
        _inc("requests_count", delta_requests)
        _inc("success_count", delta_success)
        _inc("error_count", delta_error)
        _inc("rate_limited_count", delta_rl)
        _inc("billed_units", delta_billed)
        match["updated_at"] = now_iso
        if (match["success_count"] + match["error_count"] + match["rate_limited_count"]) > match["requests_count"]:
            match["requests_count"] = match["success_count"] + match["error_count"] + match["rate_limited_count"]
        return match

    def _sum_rollups(usage, tenant_id, api_key_id, tool_name, granularity, window_start):
        ws_iso = window_start.replace(microsecond=0).isoformat() + "Z"
        total = 0
        for r in usage:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == granularity and r.get("window_start") == ws_iso:
                total += int(r.get("requests_count") or 0)
        return total

    # --- validate inputs ---
    if not isinstance(address, str) or not address.strip():
        return _err("VALIDATION_ERROR", "address 不能为空且必须为 string")
    if city is not None and not isinstance(city, str):
        return _err("VALIDATION_ERROR", "city 必须为 string")
    if output is not None and (not isinstance(output, str) or output not in ("JSON", "XML")):
        return _err("VALIDATION_ERROR", "output 枚举非法", allowed=["JSON", "XML"])
    if batch is not None and not isinstance(batch, bool):
        return _err("VALIDATION_ERROR", "batch 必须为 boolean")

