    addrs = [a.strip() for a in address.split("|")] if batch else [address.strip()]
    if batch and (len(addrs) == 0 or any(a == "" for a in addrs)):
        return _err("VALIDATION_ERROR", "batch=true 时 address 列表不能为空且不能包含空项")

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    pkeys = _load("amap_provider_keys.json")
    tool_calls = _load("tool_calls.json")
    usage = _load("usage_rollups.json")

    active_tenants = [t for t in tenants if t.get("status") == "active"]
    if not active_tenants:
        return _err("UNAUTHORIZED", "无可用租户上下文")

    chosen_tenant = None
    chosen_api_key = None
    for t in active_tenants:
        aks = [k for k in api_keys if k.get("tenant_id") == t.get("id") and k.get("status") == "active"]
        if aks:
            chosen_tenant = t
            chosen_api_key = aks[0]
            break
    if chosen_tenant is None:
        chosen_tenant = active_tenants[0]

    tenant_id = chosen_tenant.get("id")
    api_key_id = chosen_api_key.get("id") if chosen_api_key else None

    request_params = {"address": address, "city": city, "output": output, "batch": batch}
    tc = _record_call(tool_calls, tenant_id, api_key_id, None, "received", request_params, billed_units=1)

    def _finalize(status, response_body=None, error_code=None, error_message=None, http_status=None, provider_key_id=None, provider_endpoint=None, cache_key=None, cache_ttl_seconds=None):
        if status == "succeeded":
            tc["response_body"] = response_body if response_body is not None else {}
            tc["error_code"] = None
            tc["error_message"] = None
        else:
            tc["response_body"] = None
            tc["error_code"] = error_code
            tc["error_message"] = error_message
        tc["http_status"] = http_status
        tc["provider_key_id"] = provider_key_id
        tc["provider_endpoint"] = provider_endpoint
        tc["cache_key"] = cache_key
        tc["cache_ttl_seconds"] = cache_ttl_seconds
        tc["duration_ms"] = max(0, int((time.time() - t0) * 1000))
        tc["updated_at"] = now_iso

        minute_ws = _align_window(now, "minute")
        day_ws = _align_window(now, "day")
        month_ws = _align_window(now, "month")

        _upsert_rollup(usage, tenant_id, api_key_id, "maps_geo", "minute", minute_ws, delta_requests=1,
                       delta_success=1 if status == "succeeded" else 0,
                       delta_error=1 if status == "failed" else 0,
                       delta_rl=1 if status == "rate_limited" else 0,
                       delta_billed=tc.get("billed_units") or 0)
        _upsert_rollup(usage, tenant_id, None, None, "day", day_ws, delta_requests=1,
                       delta_success=1 if status == "succeeded" else 0,
                       delta_error=1 if status == "failed" else 0,
                       delta_rl=1 if status == "rate_limited" else 0,
                       delta_billed=tc.get("billed_units") or 0)
        _upsert_rollup(usage, tenant_id, None, None, "month", month_ws, delta_requests=1,
                       delta_success=1 if status == "succeeded" else 0,
                       delta_error=1 if status == "failed" else 0,
                       delta_rl=1 if status == "rate_limited" else 0,
                       delta_billed=tc.get("billed_units") or 0)

        _save("tool_calls.json", tool_calls)
        _save("usage_rollups.json", usage)

    if not _transition(tc, "validated"):
        _transition(tc, "failed")
        _finalize("failed", error_code="INVALID_TRANSITION", error_message="状态机错误", http_status=500)
        return _err("INVALID_TRANSITION", "状态机错误")

    norm = {
        "addresses": addrs,
        "city": city.strip() if isinstance(city, str) and city.strip() else None,
        "output": output or "JSON",
        "batch": bool(batch) if batch is not None else False
    }
    cache_key = hashlib.sha1(("maps_geo|" + json.dumps(norm, ensure_ascii=False, sort_keys=True)).encode("utf-8")).hexdigest()
    tc["normalized_params"] = norm
    tc["cache_key"] = cache_key
    tc["updated_at"] = now_iso

    minute_ws = _align_window(now, "minute")
    day_ws = _align_window(now, "day")
    month_ws = _align_window(now, "month")

    if chosen_api_key:
        rpm = int(chosen_api_key.get("requests_per_minute_limit") or 0)
        if rpm >= 0 and _sum_rollups(usage, tenant_id, api_key_id, "maps_geo", "minute", minute_ws) >= rpm:
            _transition(tc, "rate_limited")
            _finalize("rate_limited", error_code="RATE_LIMITED", error_message="超出 API Key 每分钟限流", http_status=429)
            return _err("RATE_LIMIT", "超出 API Key 每分钟限流", limit_per_minute=rpm)

    daily_quota = int(chosen_tenant.get("daily_request_quota") or 0)
    monthly_quota = int(chosen_tenant.get("monthly_request_quota") or 0)
    day_used = 0
    month_used = 0
    for r in usage:
        if r.get("tenant_id") == tenant_id and r.get("api_key_id") is None and r.get("tool_name") is None:
            if r.get("window_granularity") == "day" and r.get("window_start") == (day_ws.isoformat() + "Z"):
                day_used += int(r.get("requests_count") or 0)
            if r.get("window_granularity") == "month" and r.get("window_start") == (month_ws.isoformat() + "Z"):
                month_used += int(r.get("requests_count") or 0)
    if daily_quota >= 0 and day_used >= daily_quota:
        _transition(tc, "rate_limited")
        _finalize("rate_limited", error_code="QUOTA_EXCEEDED", error_message="超出租户每日配额", http_status=429)
        return _err("QUOTA_EXCEEDED", "超出租户每日配额", daily_request_quota=daily_quota)
    if monthly_quota >= 0 and month_used >= monthly_quota:
        _transition(tc, "rate_limited")
        _finalize("rate_limited", error_code="QUOTA_EXCEEDED", error_message="超出租户每月配额", http_status=429)
        return _err("QUOTA_EXCEEDED", "超出租户每月配额", monthly_request_quota=monthly_quota)

    cached = None
    for prev in reversed(tool_calls):
        if prev.get("tool_name") == "maps_geo" and prev.get("tenant_id") == tenant_id and prev.get("cache_key") == cache_key and prev.get("status") == "succeeded":
            ttl = prev.get("cache_ttl_seconds")
            created_prev = _parse_iso(prev.get("created_at"))
            if isinstance(ttl, int) and ttl >= 0 and created_prev:
                if (now - created_prev).total_seconds() <= ttl:
                    cached = prev
                    break
    if cached is not None:
        if not _transition(tc, "cache_hit") or not _transition(tc, "succeeded"):
            _transition(tc, "failed")
            _finalize("failed", error_code="INVALID_TRANSITION", error_message="缓存命中状态流转失败", http_status=500)
            return _err("INVALID_TRANSITION", "缓存命中状态流转失败")
        _finalize("succeeded", response_body=cached.get("response_body") or {}, http_status=200, cache_key=cache_key, cache_ttl_seconds=cached.get("cache_ttl_seconds"))
        return {"data": tc["response_body"], "meta": {"cached": True, "tool_call_id": tc["id"]}}

    candidates = [k for k in pkeys if k.get("tenant_id") == tenant_id and k.get("status") == "active" and isinstance(k.get("weight"), int) and k.get("weight") >= 0]
    if not candidates:
        _transition(tc, "failed")
        _finalize("failed", error_code="UNAUTHORIZED", error_message="无可用高德 provider key", http_status=401)
        return _err("UNAUTHORIZED", "无可用高德 provider key")

    # weighted selection
    total_w = sum((k.get("weight") or 0) for k in candidates)
    if total_w <= 0:
        chosen_pk = candidates[0]
    else:
        r = random.uniform(0, total_w)
        upto = 0.0
        chosen_pk = candidates[0]
        for k in candidates:
            upto += float(k.get("weight") or 0)
            if r <= upto:
                chosen_pk = k
                break

    if not _transition(tc, "dispatched"):
        _transition(tc, "failed")
        _finalize("failed", error_code="INVALID_TRANSITION", error_message="dispatched 状态流转失败", http_status=500)
        return _err("INVALID_TRANSITION", "dispatched 状态流转失败")

    # Simulate geocoding: hash address -> coords
    geos = []
    for a in addrs:
        h = hashlib.sha1((cache_key + "|" + a).encode("utf-8")).hexdigest()
        lng = (int(h[:8], 16) % 36000000) / 100000.0 - 180.0
        lat = (int(h[8:16], 16) % 18000000) / 100000.0 - 90.0
        geos.append({
            "input_address": a,
            "location": f"{lng:.6f},{lat:.6f}",
            "formatted_address": a.strip(),
            "country": "中国",
            "province": "",
            "city": (city.strip() if isinstance(city, str) else "") or "",
            "district": "",
            "adcode": ""
        })

    response = {"count": len(geos), "geocodes": geos}
    ttl = 3600
    tc["cache_ttl_seconds"] = ttl

    if chosen_api_key:
        chosen_api_key["last_used_at"] = now_iso
        chosen_api_key["updated_at"] = now_iso
        _save("api_keys.json", api_keys)

    if not _transition(tc, "succeeded"):
        _transition(tc, "failed")
        _finalize("failed", error_code="INVALID_TRANSITION", error_message="succeeded 状态流转失败", http_status=500, provider_key_id=chosen_pk.get("id"), provider_endpoint="amap/geo", cache_key=cache_key, cache_ttl_seconds=ttl)
        return _err("INVALID_TRANSITION", "succeeded 状态流转失败")

    _finalize("succeeded", response_body=response, http_status=200, provider_key_id=chosen_pk.get("id"), provider_endpoint="amap/geo", cache_key=cache_key, cache_ttl_seconds=ttl)
    return {"data": response, "meta": {"cached": False, "tool_call_id": tc["id"]}}

def maps_ip_location(ip, output=None, **_extra):
