def maps_weather(city, extensions=None, output=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    def _parse_iso(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _align_window(dt, granularity):
        if granularity == "minute":
            return dt.replace(second=0, microsecond=0)
        if granularity == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if granularity == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _new_id(prefix):
        return f"{prefix}_{hashlib.sha1((str(time.time_ns()) + '|' + str(random.random())).encode('utf-8')).hexdigest()[:16]}"

    def _record_call(tool_calls, tenant_id, api_key_id, provider_key_id, status, request_params, normalized_params=None,
                     cache_key=None, cache_ttl_seconds=None, http_status=None, provider_endpoint=None,
                     response_body=None, error_code=None, error_message=None, billed_units=1):
        tc_id = _new_id("tc")
        row = {
            "id": tc_id,
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "provider_key_id": provider_key_id,
            "mcp_session_id": None,
            "tool_name": "maps_weather",
            "status": status,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "normalized_params": normalized_params,
            "cache_key": cache_key,
            "cache_ttl_seconds": cache_ttl_seconds,
            "http_status": http_status,
            "provider_endpoint": provider_endpoint,
            "provider_request_id": None,
            "response_body": response_body,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": None,
            "billed_units": int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1,
            "created_at": now_iso,
            "updated_at": now_iso
        }
        tool_calls.append(row)
        return row

    def _transition(row, new_status):
        transitions = {
            "received": ["validated", "failed", "rate_limited"],
            "validated": ["cache_hit", "dispatched", "failed", "rate_limited"],
            "cache_hit": ["succeeded"],
            "dispatched": ["succeeded", "failed"],
            "succeeded": [],
            "failed": [],
            "rate_limited": []
        }
        cur = row.get("status")
        if new_status == cur:
            return True
        if cur not in transitions or new_status not in transitions[cur]:
            return False
        row["status"] = new_status
        row["updated_at"] = now_iso
        return True

    def _upsert_rollup(usage, tenant_id, api_key_id, tool_name, granularity, window_start, delta_requests=0,
                       delta_success=0, delta_error=0, delta_rl=0, delta_billed=0):
        ws_iso = window_start.replace(microsecond=0).isoformat() + "Z"
        match = None
        for r in usage:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == granularity and r.get("window_start") == ws_iso:
                match = r
                break
        if match is None:
            match = {
                "id": _new_id("ur"),
                "tenant_id": tenant_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "window_start": ws_iso,
                "window_granularity": granularity,
                "requests_count": 0,
                "success_count": 0,
                "error_count": 0,
                "rate_limited_count": 0,
                "billed_units": 0,
                "created_at": now_iso,
                "updated_at": now_iso
            }
            usage.append(match)
        def _inc(k, dv):
            if dv:
                match[k] = int(match.get(k) or 0) + int(dv)
        _inc("requests_count", delta_requests)
        _inc("success_count", delta_success)
        _inc("error_count", delta_error)
        _inc("rate_limited_count", delta_rl)
        _inc("billed_units", delta_billed)
        match["updated_at"] = now_iso
        if (match["success_count"] + match["error_count"] + match["rate_limited_count"]) > match["requests_count"]:
            match["requests_count"] = match["success_count"] + match["error_count"] + match["rate_limited_count"]
        return match

    def _sum_rollups(usage, tenant_id, api_key_id, tool_name, granularity, window_start):
        ws_iso = window_start.replace(microsecond=0).isoformat() + "Z"
        total = 0
        for r in usage:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == granularity and r.get("window_start") == ws_iso:
                total += int(r.get("requests_count") or 0)
        return total

    # validate
    if not isinstance(city, str) or not city.strip():
        return _err("VALIDATION_ERROR", "city 不能为空且必须为 string")
    if extensions is not None and (not isinstance(extensions, str) or extensions not in ("base", "all")):
        return _err("VALIDATION_ERROR", "extensions 枚举非法", allowed=["base", "all"])
    if output is not None and (not isinstance(output, str) or output not in ("JSON", "XML")):
