    tc = _record_call(tool_calls, tenant_id, api_key_id, None, "received", request_params, billed_units=1)

    def _finalize(status, response_body=None, error_code=None, error_message=None, http_status=None, provider_key_id=None, provider_endpoint=None, cache_key=None, cache_ttl_seconds=None):
        if status == "succeeded":
