        seed = int(datetime.datetime.utcnow().strftime("%Y%m%d%H%M"))
        rnd = random.Random(seed)
        total = sum(w for _, w in weighted)
        r = rnd.uniform(0, total)
        upto = 0.0
        for p, w in weighted:
            upto += w
            if r <= upto:
