        for t in tenants:
            if t.get("status") != "active":
                continue
            t_id = t.get("id")
            pks = [p for p in provider_keys if p.get("tenant_id") == t_id and p.get("status") == "active"]
            if not pks:
                continue
            aks = [k for k in api_keys if k.get("tenant_id") == t_id and k.get("status") == "active"]
            viable.append((t, aks, pks))
        if not viable:
            return None, None, None
        viable.sort(key=lambda x: sum(int(p.get("weight") or 0) for p in x[2]), reverse=True)
        t, aks, pks = viable[0]
        ak = aks[0] if aks else None
        return t, ak, pks

