            "duration": dur,
            "segments": [
                {"mode": "walk", "instruction": "步行至附近站点", "distance": 500 + (h % 300), "duration": 420 + (h % 180)},
                {"mode": "subway", "instruction": "乘坐地铁/轨交", "distance": int(dist * 0.65), "duration": int(dur * 0.55)},
                {"mode": "bus", "instruction": "换乘公交", "distance": int(dist * 0.25), "duration": int(dur * 0.30)},
                {"mode": "walk", "instruction": "步行至目的地", "distance": 600 + (h % 400), "duration": 520 + (h % 240)}
            ]
        })

    response = {
        "transit": {
            "origin_city": oc,
            "destination_city": dc,
            "origin_address": oa,
            "destination_address": da,
            "routes": transits
        }
    }

    latency = int((time.time() - t0) * 1000)
    _update_tool_call(call_id, {"status": "succeeded", "http_status": 200, "response_body": response, "duration_ms": latency, "provider_request_id": _new_id("amapreq")})
    if api_key_id:
        api_keys = _load("api_keys.json")
        for i, k in enumerate(api_keys):
            if k.get("id") == api_key_id:
                api_keys[i] = dict(k)
                api_keys[i]["last_used_at"] = now
                api_keys[i]["updated_at"] = now
                _save("api_keys.json", api_keys)
                break
    _inc_rollups(tenant_id, api_key_id, tool_name, "succeeded", 1)
    return {"data": response, "meta": {"cached": False, "tool_call_id": call_id}}

def maps_direction_transit_integrated_by_coordinates(origin, destination, city, cityd, **_extra):
    import json, os, datetime, time, hashlib, random, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S')}_{hashlib.sha256(os.urandom(16)).hexdigest()[:16]}"

    def _align_window(dt, gran):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if gran == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if gran == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _iso(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _normalize_space(s):
        s = s.strip()
        s = re.sub(r"\s+", " ", s)
        return s

    def _parse_lnglat(s):
        if not isinstance(s, str):
            return None
        parts = [p.strip() for p in s.split(",")]
        if len(parts) != 2:
            return None
        try:
            lng = float(parts[0]); lat = float(parts[1])
        except Exception:
            return None
        if not (-180.0 <= lng <= 180.0 and -90.0 <= lat <= 90.0):
            return None
        return f"{lng:.6f},{lat:.6f}", lng, lat

    def _make_cache_key(tool_name, normalized_params):
        blob = json.dumps({"tool_name": tool_name, "normalized_params": normalized_params}, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(blob.encode("utf-8")).hexdigest()

    def _pick_context():
        tenants = _load("tenants.json")
        api_keys = _load("api_keys.json")
        provider_keys = _load("amap_provider_keys.json")
        viable = []
        for t in tenants:
            if t.get("status") != "active":
                continue
            t_id = t.get("id")
            pks = [p for p in provider_keys if p.get("tenant_id") == t_id and p.get("status") == "active"]
            if not pks:
                continue
            aks = [k for k in api_keys if k.get("tenant_id") == t_id and k.get("status") == "active"]
            viable.append((t, aks, pks))
        if not viable:
            return None, None, None
        viable.sort(key=lambda x: sum(int(p.get("weight") or 0) for p in x[2]), reverse=True)
        t, aks, pks = viable[0]
        ak = aks[0] if aks else None
        return t, ak, pks

    def _get_or_create_rollup(rollups, tenant_id, api_key_id, tool_name, gran, window_start_iso):
        for r in rollups:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == gran and r.get("window_start") == window_start_iso:
                return r
        r = {
            "id": _new_id("ur"),
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "window_start": window_start_iso,
            "window_granularity": gran,
            "requests_count": 0,
            "success_count": 0,
            "error_count": 0,
            "rate_limited_count": 0,
            "billed_units": 0,
            "created_at": now,
            "updated_at": now
        }
        rollups.append(r)
        return r

    def _inc_rollups(tenant_id, api_key_id, tool_name, outcome, billed_units):
        rollups = _load("usage_rollups.json")
        dt = datetime.datetime.utcnow()
        minute = _iso(_align_window(dt, "minute"))
        day = _iso(_align_window(dt, "day"))
        month = _iso(_align_window(dt, "month"))

        def upd(api_key_for_row, tool_for_row, gran, ws):
            r = _get_or_create_rollup(rollups, tenant_id, api_key_for_row, tool_for_row, gran, ws)
            r["requests_count"] = int(r.get("requests_count") or 0) + 1
            if outcome == "succeeded":
                r["success_count"] = int(r.get("success_count") or 0) + 1
            elif outcome == "rate_limited":
                r["rate_limited_count"] = int(r.get("rate_limited_count") or 0) + 1
            else:
                r["error_count"] = int(r.get("error_count") or 0) + 1
            r["billed_units"] = int(r.get("billed_units") or 0) + int(billed_units or 0)
            r["updated_at"] = now

        if api_key_id:
            upd(api_key_id, tool_name, "minute", minute)
            upd(api_key_id, None, "minute", minute)

        upd(None, None, "day", day)
        upd(None, tool_name, "day", day)
        upd(None, None, "month", month)
        upd(None, tool_name, "month", month)

        _save("usage_rollups.json", rollups)

    def _tenant_quota_exceeded(tenant_id):
        tenants = _load("tenants.json")
        t = next((x for x in tenants if x.get("id") == tenant_id), None)
        if not t:
            return True, "NOT_FOUND"
        daily_quota = int(t.get("daily_request_quota") or 0)
        monthly_quota = int(t.get("monthly_request_quota") or 0)
        rollups = _load("usage_rollups.json")
        dt = datetime.datetime.utcnow()
        day = _iso(_align_window(dt, "day"))
        month = _iso(_align_window(dt, "month"))
        day_row = next((r for r in rollups if r.get("tenant_id") == tenant_id and r.get("api_key_id") is None and r.get("tool_name") is None and r.get("window_granularity") == "day" and r.get("window_start") == day), None)
        month_row = next((r for r in rollups if r.get("tenant_id") == tenant_id and r.get("api_key_id") is None and r.get("tool_name") is None and r.get("window_granularity") == "month" and r.get("window_start") == month), None)
        day_count = int(day_row.get("requests_count") or 0) if day_row else 0
        month_count = int(month_row.get("requests_count") or 0) if month_row else 0
        if daily_quota >= 0 and day_count >= daily_quota:
            return True, "daily_request_quota"
        if monthly_quota >= 0 and month_count >= monthly_quota:
            return True, "monthly_request_quota"
        return False, None

    def _api_key_rate_limited(api_key_row, tenant_id):
        if not api_key_row:
            return False
        if api_key_row.get("tenant_id") != tenant_id or api_key_row.get("status") != "active":
            return True
        limit = int(api_key_row.get("requests_per_minute_limit") or 0)
        rollups = _load("usage_rollups.json")
        dt = datetime.datetime.utcnow()
        minute = _iso(_align_window(dt, "minute"))
        row = next((r for r in rollups if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_row.get("id") and r.get("tool_name") is None and r.get("window_granularity") == "minute" and r.get("window_start") == minute), None)
        count = int(row.get("requests_count") or 0) if row else 0
        return limit >= 0 and count >= limit

    def _select_provider_key(pks):
        if not pks:
            return None
        weighted = []
        for p in pks:
            w = int(p.get("weight") or 0)
            if w <= 0:
                w = 1
            weighted.append((p, w))
        seed = int(datetime.datetime.utcnow().strftime("%Y%m%d%H%M"))
        rnd = random.Random(seed)
        total = sum(w for _, w in weighted)
        r = rnd.uniform(0, total)
        upto = 0.0
        for p, w in weighted:
            upto += w
            if r <= upto:
                return p
        return weighted[-1][0]

    def _log_tool_call(row):
        tool_calls = _load("tool_calls.json")
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    def _update_tool_call(call_id, patch):
        tool_calls = _load("tool_calls.json")
        for i, r in enumerate(tool_calls):
            if r.get("id") == call_id:
                nr = dict(r)
                nr.update(patch)
                nr["updated_at"] = now
                tool_calls[i] = nr
                _save("tool_calls.json", tool_calls)
                return nr
        return None

    # Validate
    po = _parse_lnglat(origin)
    if not po:
        return _err("VALIDATION_ERROR", "origin must be in 'lng,lat' format and within valid ranges")
    pd = _parse_lnglat(destination)
    if not pd:
        return _err("VALIDATION_ERROR", "destination must be in 'lng,lat' format and within valid ranges")
    if not isinstance(city, str) or not city.strip():
        return _err("VALIDATION_ERROR", "city is required and must be a non-empty string")
    if not isinstance(cityd, str) or not cityd.strip():
        return _err("VALIDATION_ERROR", "cityd is required and must be a non-empty string")

    tool_name = "maps_direction_transit_integrated_by_coordinates"
    req_params = {"origin": origin, "destination": destination, "city": city, "cityd": cityd}

    tenant, api_key, provider_keys = _pick_context()
    if not tenant:
        return _err("UNAUTHORIZED", "No active tenant/provider key available to serve this request")

    tenant_id = tenant.get("id")
    api_key_id = api_key.get("id") if api_key else None

    call_id = _new_id("tc")
    base_call = {
        "id": call_id,
        "tenant_id": tenant_id,
        "api_key_id": api_key_id,
        "provider_key_id": None,
        "mcp_session_id": _extra.get("mcp_session_id"),
        "tool_name": tool_name,
        "status": "received",
        "request_params": req_params,
        "normalized_params": None,
        "cache_key": None,
        "cache_ttl_seconds": 1800,
        "http_status": None,
        "provider_endpoint": None,
        "provider_request_id": None,
        "response_body": None,
        "error_code": None,
        "error_message": None,
        "duration_ms": None,
        "billed_units": 1,
        "created_at": now,
        "updated_at": now
    }
    _log_tool_call(base_call)

    if tenant.get("status") in ("suspended", "deleted"):
        _update_tool_call(call_id, {"status": "failed", "http_status": 403, "error_code": "TENANT_SUSPENDED", "error_message": "Tenant is not active"})
        _inc_rollups(tenant_id, api_key_id, tool_name, "failed", 0)
        return _err("UNAUTHORIZED", "Tenant is not active")

    exceeded, which = _tenant_quota_exceeded(tenant_id)
    if exceeded:
        _update_tool_call(call_id, {"status": "rate_limited", "http_status": 429, "error_code": "QUOTA_EXCEEDED", "error_message": f"Tenant quota exceeded: {which}"})
        _inc_rollups(tenant_id, api_key_id, tool_name, "rate_limited", 0)
        return _err("QUOTA_EXCEEDED", f"Tenant quota exceeded: {which}")

    if _api_key_rate_limited(api_key, tenant_id):
        _update_tool_call(call_id, {"status": "rate_limited", "http_status": 429, "error_code": "RATE_LIMITED", "error_message": "API key rate limit exceeded"})
        _inc_rollups(tenant_id, api_key_id, tool_name, "rate_limited", 0)
        return _err("RATE_LIMIT", "API key rate limit exceeded")

    _update_tool_call(call_id, {"status": "validated"})

    norm = {
        "origin": po[0],
        "destination": pd[0],
        "city": _normalize_space(city),
        "cityd": _normalize_space(cityd)
    }
    cache_key = _make_cache_key(tool_name, norm)
    _update_tool_call(call_id, {"normalized_params": norm, "cache_key": cache_key})

    tool_calls = _load("tool_calls.json")
    cached = None
    for r in reversed(tool_calls):
        if r.get("cache_key") == cache_key and r.get("tool_name") == tool_name and r.get("status") == "succeeded" and isinstance(r.get("response_body"), dict):
            ttl = r.get("cache_ttl_seconds")
            created = _parse_dt(r.get("created_at"))
            if ttl is None or created is None:
                cached = r
                break
            if (datetime.datetime.utcnow() - created).total_seconds() <= int(ttl):
                cached = r
                break

    if cached:
        _update_tool_call(call_id, {"status": "cache_hit"})
        resp = cached.get("response_body")
        latency = int((time.time() - t0) * 1000)
        _update_tool_call(call_id, {"status": "succeeded", "http_status": 200, "response_body": resp, "duration_ms": latency})
        if api_key_id:
            api_keys = _load("api_keys.json")
            for i, k in enumerate(api_keys):
                if k.get("id") == api_key_id:
                    api_keys[i] = dict(k)
                    api_keys[i]["last_used_at"] = now
                    api_keys[i]["updated_at"] = now
                    _save("api_keys.json", api_keys)
                    break
        _inc_rollups(tenant_id, api_key_id, tool_name, "succeeded", 1)
        return {"data": resp, "meta": {"cached": True, "tool_call_id": call_id}}

    pk = _select_provider_key(provider_keys)
    if not pk:
        _update_tool_call(call_id, {"status": "failed", "http_status": 503, "error_code": "NO_PROVIDER_KEY", "error_message": "No active provider key available"})
        _inc_rollups(tenant_id, api_key_id, tool_name, "failed", 0)
        return _err("UNAUTHORIZED", "No provider key available")

    _update_tool_call(call_id, {"status": "dispatched", "provider_key_id": pk.get("id"), "provider_endpoint": "amap/direction/transit/integrated"})

    # Basic consistency rule: if city/cityd are identical but distance huge -> NOT_FOUND (likely mismatch)
    _, lng1, lat1 = po
    _, lng2, lat2 = pd
    # equirectangular approximation
    import math
    x = (math.radians(lng2 - lng1)) * math.cos(math.radians((lat1 + lat2) / 2.0))
    y = math.radians(lat2 - lat1)
    straight = 6371000.0 * math.sqrt(x*x + y*y)

    c1 = norm["city"].lower()
    c2 = norm["cityd"].lower()
    if c1 == c2 and straight > 250000:  # 250km within same "city" is suspicious
        latency = int((time.time() - t0) * 1000)
        _update_tool_call(call_id, {"status": "failed", "http_status": 404, "error_code": "NOT_FOUND", "error_message": "city/cityd conflict with coordinates", "duration_ms": latency})
        _inc_rollups(tenant_id, api_key_id, tool_name, "failed", 1)
        return _err("NOT_FOUND", "city/cityd conflict with coordinates")

    if straight < 80:
        latency = int((time.time() - t0) * 1000)
        _update_tool_call(call_id, {"status": "failed", "http_status": 404, "error_code": "NOT_FOUND", "error_message": "No transit plan found", "duration_ms": latency})
        _inc_rollups(tenant_id, api_key_id, tool_name, "failed", 1)
        return _err("NOT_FOUND", "No transit plan found")

    h = int(hashlib.sha256((po[0] + "|" + pd[0] + "|" + c1 + "|" + c2).encode("utf-8")).hexdigest()[:8], 16)
    base_dist = int(straight * (1.10 + (h % 15) / 100.0))
    base_dur = int(base_dist / 1.1)  # seconds, includes waiting/transfer inflated later
    routes = []
    n = 2 + (h % 2)
    for i in range(n):
        dist = base_dist + i * 700
        dur = base_dur + i * 500 + 600  # add waiting
        routes.append({
            "distance": dist,
            "duration": dur,
            "segments": [
                {"mode": "walk", "distance": 400 + (h % 300), "duration": 360 + (h % 180), "instruction": "步行至站点"},
                {"mode": "bus_or_subway", "distance": int(dist * 0.8), "duration": int(dur * 0.7), "instruction": "乘坐公共交通"},
                {"mode": "walk", "distance": 500 + (h % 400), "duration": 420 + (h % 240), "instruction": "步行至目的地"}
            ]
        })

    response = {
        "transit": {
            "city": norm["city"],
            "cityd": norm["cityd"],
            "origin": po[0],
            "destination": pd[0],
            "routes": routes
        }
    }

    latency = int((time.time() - t0) * 1000)
    _update_tool_call(call_id, {"status": "succeeded", "http_status": 200, "response_body": response, "duration_ms": latency, "provider_request_id": _new_id("amapreq")})
    if api_key_id:
        api_keys = _load("api_keys.json")
        for i, k in enumerate(api_keys):
            if k.get("id") == api_key_id:
                api_keys[i] = dict(k)
                api_keys[i]["last_used_at"] = now
                api_keys[i]["updated_at"] = now
                _save("api_keys.json", api_keys)
                break
    _inc_rollups(tenant_id, api_key_id, tool_name, "succeeded", 1)
    return {"data": response, "meta": {"cached": False, "tool_call_id": call_id}}

def maps_distance(origins, destination, type=None, **_extra):
    import json, os, datetime, time, math, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randrange(100000, 999999)}"

    def _parse_coord(s):
        if not isinstance(s, str):
            return None
        s = s.strip()
        parts = s.split(",")
        if len(parts) != 2:
            return None
        try:
            lng = float(parts[0].strip())
            lat = float(parts[1].strip())
        except Exception:
            return None
        if not (-180.0 <= lng <= 180.0 and -90.0 <= lat <= 90.0):
            return None
        return (lng, lat)

    def _normalize_coord_str(s):
        c = _parse_coord(s)
        if c is None:
            return None
        return f"{c[0]:.6f},{c[1]:.6f}"

    def _haversine_m(a, b):
        lng1, lat1 = a
        lng2, lat2 = b
        r = 6371000.0
        phi1 = math.radians(lat1)
        phi2 = math.radians(lat2)
        dphi = math.radians(lat2 - lat1)
        dl = math.radians(lng2 - lng1)
        x = math.sin(dphi / 2.0) ** 2 + math.cos(phi1) * math.cos(phi2) * math.sin(dl / 2.0) ** 2
        return 2.0 * r * math.asin(min(1.0, math.sqrt(x)))

    def _sha(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _pick_auth_context():
        tenants = _load("tenants.json")
        api_keys = _load("api_keys.json")
        provider_keys = _load("amap_provider_keys.json")

        # Prefer a tenant that can actually serve requests: tenant active + has at least one active provider key.
        # api_key is optional in schema; calls may be unauthenticated at caller-level, but must still map to a tenant.
        viable = []
        for t in tenants:
            if t.get("status") != "active":
                continue
            t_id = t.get("id")
            if not isinstance(t_id, str) or not t_id:
                continue
            pks = [p for p in provider_keys if p.get("tenant_id") == t_id and p.get("status") == "active"]
            if not pks:
                continue
            # attach an active api key if exists
            aks = [a for a in api_keys if a.get("tenant_id") == t_id and a.get("status") == "active"]
            viable.append((t, aks[0] if aks else None, pks))
        if not viable:
            # If no active tenant has active provider keys, still allow cache-hit only flows; pick any active tenant.
            for t in tenants:
                if t.get("status") == "active" and isinstance(t.get("id"), str) and t.get("id"):
                    t_id = t["id"]
                    aks = [a for a in api_keys if a.get("tenant_id") == t_id and a.get("status") == "active"]
                    return (t, aks[0] if aks else None, [])
            return None
        # Deterministic pick: highest tenant quota then name.
        viable.sort(key=lambda x: (int(x[0].get("daily_request_quota", 0)), str(x[0].get("name", ""))), reverse=True)
        return viable[0]

    def _rollup_key(tenant_id, api_key_id, tool_name, gran, window_start):
        base = f"{tenant_id}|{api_key_id or ''}|{tool_name or ''}|{gran}|{window_start}"
        return "ur_" + _sha(base)[:24]

    def _align_window(dt, gran):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if gran == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if gran == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _get_or_create_rollup(usage, tenant_id, api_key_id, tool_name, gran, window_start_iso):
        for r in usage:
            if (
                r.get("tenant_id") == tenant_id
                and r.get("api_key_id") == api_key_id
                and r.get("tool_name") == tool_name
                and r.get("window_granularity") == gran
                and r.get("window_start") == window_start_iso
            ):
                return r
        now = _now()
        r = {
            "id": _rollup_key(tenant_id, api_key_id, tool_name, gran, window_start_iso),
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "window_start": window_start_iso,
            "window_granularity": gran,
            "requests_count": 0,
            "success_count": 0,
            "error_count": 0,
            "rate_limited_count": 0,
            "billed_units": 0,
            "created_at": now,
            "updated_at": now,
        }
        usage.append(r)
        return r

    def _enforce_limits_and_log_received(ctx, request_params, normalized_params, cache_key):
        tool_calls = _load("tool_calls.json")
        usage = _load("usage_rollups.json")
        api_keys = _load("api_keys.json")
        tenants = _load("tenants.json")

        t, ak, provider_keys = ctx
        tenant_id = t["id"]
        api_key_id = ak["id"] if ak else None

        start = time.time()
        now_dt = datetime.datetime.utcnow()
        now_iso = _now()

        call_id = _gen_id("tc")
        tc = {
            "id": call_id,
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "provider_key_id": None,
            "mcp_session_id": None,
            "tool_name": "maps_distance",
            "status": "received",
            "request_params": request_params,
            "normalized_params": normalized_params,
            "cache_key": cache_key,
            "cache_ttl_seconds": 300,
            "http_status": None,
            "provider_endpoint": None,
            "provider_request_id": None,
            "response_body": None,
            "error_code": None,
            "error_message": None,
            "duration_ms": None,
            "billed_units": 1,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        tool_calls.append(tc)

        def _finish_and_persist(status, http_status=None, response_body=None, err_code=None, err_msg=None, provider_key_id=None, provider_endpoint=None, billed_units=1):
            end = time.time()
            tc["status"] = status
            tc["http_status"] = http_status
            tc["response_body"] = response_body
            tc["error_code"] = err_code
            tc["error_message"] = err_msg
            tc["provider_key_id"] = provider_key_id
            tc["provider_endpoint"] = provider_endpoint
            tc["billed_units"] = int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1
            tc["duration_ms"] = int(round((end - start) * 1000))
            tc["updated_at"] = _now()

            # Integrity rules
            if tc["status"] != "succeeded":
                tc["response_body"] = None
            if tc["status"] not in ("failed", "rate_limited"):
                tc["error_code"] = None
                tc["error_message"] = None

            # Update api_key last_used_at on success
            if tc["status"] == "succeeded" and api_key_id:
                for a in api_keys:
                    if a.get("id") == api_key_id:
                        a["last_used_at"] = tc["updated_at"]
                        a["updated_at"] = tc["updated_at"]
                        break

            # Usage rollups (requests always increment; billed_units tracked; outcome counters updated)
            minute_start = _align_window(now_dt, "minute").replace(microsecond=0).isoformat() + "Z"
            day_start = _align_window(now_dt, "day").replace(microsecond=0).isoformat() + "Z"
            month_start = _align_window(now_dt, "month").replace(microsecond=0).isoformat() + "Z"

            def bump(api_key_scope):
                # api_key_scope: api_key_id or None
                # minute: per api key and tool
                r_min = _get_or_create_rollup(usage, tenant_id, api_key_scope, "maps_distance", "minute", minute_start)
                r_min["requests_count"] += 1
                if tc["status"] == "succeeded":
                    r_min["success_count"] += 1
                elif tc["status"] == "rate_limited":
                    r_min["rate_limited_count"] += 1
                else:
                    r_min["error_count"] += 1
                r_min["billed_units"] += tc["billed_units"]
                r_min["updated_at"] = tc["updated_at"]

                # day: tenant quota
                r_day = _get_or_create_rollup(usage, tenant_id, api_key_scope, None, "day", day_start)
                r_day["requests_count"] += 1
                if tc["status"] == "succeeded":
                    r_day["success_count"] += 1
                elif tc["status"] == "rate_limited":
                    r_day["rate_limited_count"] += 1
                else:
                    r_day["error_count"] += 1
                r_day["billed_units"] += tc["billed_units"]
                r_day["updated_at"] = tc["updated_at"]

                # month: tenant quota
                r_mon = _get_or_create_rollup(usage, tenant_id, api_key_scope, None, "month", month_start)
                r_mon["requests_count"] += 1
                if tc["status"] == "succeeded":
                    r_mon["success_count"] += 1
                elif tc["status"] == "rate_limited":
                    r_mon["rate_limited_count"] += 1
                else:
                    r_mon["error_count"] += 1
                r_mon["billed_units"] += tc["billed_units"]
                r_mon["updated_at"] = tc["updated_at"]

            bump(api_key_id)   # api_key level (if None, treated as tenant-only in same row shape)
            if api_key_id is not None:
                bump(None)     # tenant aggregate as well

            _save("tool_calls.json", tool_calls)
            _save("usage_rollups.json", usage)
            _save("api_keys.json", api_keys)
            _save("tenants.json", tenants)

        # Validate tenant & api_key lifecycle constraints early; record as failed or rate_limited per rule
        if t.get("status") in ("suspended", "deleted"):
            _finish_and_persist(
                "rate_limited",
                http_status=429,
                err_code="TENANT_SUSPENDED",
                err_msg="Tenant is not allowed to create new tool calls",
            )
            return ("RATE_LIMIT", "Tenant suspended/deleted", tc)

        if api_key_id:
            ak_row = None
            for a in api_keys:
                if a.get("id") == api_key_id:
                    ak_row = a
                    break
            if not ak_row or ak_row.get("status") != "active" or ak_row.get("tenant_id") != tenant_id:
                _finish_and_persist(
                    "failed",
                    http_status=401,
                    err_code="UNAUTHORIZED",
                    err_msg="Invalid or inactive api key for tenant",
                )
                return ("UNAUTHORIZED", "Unauthorized", tc)

        # Enforce api_key per-minute limit (if present)
        if api_key_id:
            minute_start = _align_window(now_dt, "minute").replace(microsecond=0).isoformat() + "Z"
            r_min = None
            for r in usage:
                if (
                    r.get("tenant_id") == tenant_id
                    and r.get("api_key_id") == api_key_id
                    and r.get("tool_name") == "maps_distance"
                    and r.get("window_granularity") == "minute"
                    and r.get("window_start") == minute_start
                ):
                    r_min = r
                    break
            current = int(r_min.get("requests_count", 0)) if r_min else 0
            limit = int(ak.get("requests_per_minute_limit", 0)) if ak and isinstance(ak.get("requests_per_minute_limit"), int) else 0
            if limit >= 0 and current >= limit:
                _finish_and_persist(
                    "rate_limited",
                    http_status=429,
                    err_code="RATE_LIMIT",
                    err_msg="API key per-minute request limit reached",
                )
                return ("RATE_LIMIT", "Rate limit reached", tc)

        # Enforce tenant daily/monthly quota
        day_start = _align_window(now_dt, "day").replace(microsecond=0).isoformat() + "Z"
        month_start = _align_window(now_dt, "month").replace(microsecond=0).isoformat() + "Z"
        daily_q = int(t.get("daily_request_quota", 0)) if isinstance(t.get("daily_request_quota"), int) else 0
        monthly_q = int(t.get("monthly_request_quota", 0)) if isinstance(t.get("monthly_request_quota"), int) else 0

        def _tenant_count(gran, wstart):
            for r in usage:
                if (
                    r.get("tenant_id") == tenant_id
                    and r.get("api_key_id") is None
                    and r.get("tool_name") is None
                    and r.get("window_granularity") == gran
                    and r.get("window_start") == wstart
                ):
                    return int(r.get("requests_count", 0))
            return 0

        if daily_q >= 0 and _tenant_count("day", day_start) >= daily_q:
            _finish_and_persist("rate_limited", http_status=429, err_code="QUOTA_DAILY", err_msg="Tenant daily quota exceeded")
            return ("QUOTA_EXCEEDED", "Daily quota exceeded", tc)

        if monthly_q >= 0 and _tenant_count("month", month_start) >= monthly_q:
            _finish_and_persist("rate_limited", http_status=429, err_code="QUOTA_MONTHLY", err_msg="Tenant monthly quota exceeded")
            return ("QUOTA_EXCEEDED", "Monthly quota exceeded", tc)

        # Transition to validated
        tc["status"] = "validated"
        tc["updated_at"] = _now()
        _save("tool_calls.json", tool_calls)
        return ("OK", None, tc)

    # ---- Input validation ----
    if not isinstance(origins, str) or not origins.strip():
        return _err("VALIDATION_ERROR", "origins must be a non-empty string")
    if not isinstance(destination, str) or not destination.strip():
        return _err("VALIDATION_ERROR", "destination must be a non-empty string")
    if type is None:
        type = "driving"
    if not isinstance(type, str) or type not in ("driving", "walking", "distance"):
        return _err("VALIDATION_ERROR", "type must be one of: driving, walking, distance")

    origin_parts = [p.strip() for p in origins.split("|") if p.strip()]
    if not origin_parts:
        return _err("VALIDATION_ERROR", "origins must contain at least one coordinate")

    norm_origins = []
    parsed_origins = []
    for p in origin_parts:
        n = _normalize_coord_str(p)
        if n is None:
            return _err("VALIDATION_ERROR", f"Invalid origin coordinate: {p}")
        norm_origins.append(n)
        parsed_origins.append(_parse_coord(n))

    norm_dest = _normalize_coord_str(destination)
    if norm_dest is None:
        return _err("VALIDATION_ERROR", "Invalid destination coordinate")
    parsed_dest = _parse_coord(norm_dest)

    request_params = {"origins": origins, "destination": destination, "type": type}
    normalized_params = {"origins": "|".join(norm_origins), "destination": norm_dest, "type": type}
    cache_key = "ck_" + _sha("maps_distance|" + json.dumps(normalized_params, ensure_ascii=False, sort_keys=True))[:32]

    # ---- Resolve auth/workspace context ----
    ctx = _pick_auth_context()
    if ctx is None:
        return _err("UNAUTHORIZED", "No authorized tenant context available")

    # ---- Create tool_call, enforce limits, and proceed ----
    pre = _enforce_limits_and_log_received(ctx, request_params, normalized_params, cache_key)
    if isinstance(pre, dict) and pre.get("error"):
        return pre
    code, msg, tc = pre
    if code != "OK":
        if code == "RATE_LIMIT":
            return _err("RATE_LIMIT", msg)
        if code == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", msg)
        if code == "UNAUTHORIZED":
            return _err("UNAUTHORIZED", msg)
        return _err("VALIDATION_ERROR", msg or "Request rejected")

    # ---- Cache lookup ----
    tool_calls = _load("tool_calls.json")
    cached = None
    for row in reversed(tool_calls):
        if row.get("cache_key") == cache_key and row.get("status") == "succeeded" and isinstance(row.get("response_body"), dict):
            cached = row
            break

    def _persist_update(tc_id, **updates):
        now = _now()
        updated = False
        for row in tool_calls:
            if row.get("id") == tc_id:
                # lifecycle transitions
                transitions = {
                    "received": {"validated", "failed", "rate_limited"},
                    "validated": {"cache_hit", "dispatched", "failed", "rate_limited"},
                    "cache_hit": {"succeeded"},
                    "dispatched": {"succeeded", "failed"},
                    "succeeded": set(),
                    "failed": set(),
                    "rate_limited": set(),
                }
                if "status" in updates:
                    old = row.get("status")
                    new = updates["status"]
                    if new != old:
                        if new not in transitions.get(old, set()):
                            row["error_code"] = "INVALID_TRANSITION"
                            row["error_message"] = f"Illegal transition {old} -> {new}"
                            row["status"] = "failed"
                        else:
                            row["status"] = new
                for k, v in updates.items():
                    if k == "status":
                        continue
                    row[k] = v
                row["updated_at"] = now

                # integrity rules
                if row.get("status") != "succeeded":
                    row["response_body"] = None
                if row.get("status") not in ("failed", "rate_limited"):
                    row["error_code"] = None
                    row["error_message"] = None
                updated = True
                break
        if updated:
            _save("tool_calls.json", tool_calls)
        return updated

    if cached is not None:
        _persist_update(tc["id"], status="cache_hit", provider_endpoint=None, provider_key_id=None)
        # then succeeded
        resp = cached.get("response_body")
        _persist_update(tc["id"], status="succeeded", http_status=200, response_body=resp, provider_endpoint=None, provider_key_id=None)
        return {
            "results": resp.get("results", []),
            "type": resp.get("type"),
            "origins_count": resp.get("origins_count"),
            "destination": resp.get("destination"),
            "meta": {"cached": True, "tool_call_id": tc["id"]},
        }

    # ---- Dispatch (simulate provider call offline) ----
    tenant_id = ctx[0]["id"]
    provider_keys = _load("amap_provider_keys.json")
    candidates = [p for p in provider_keys if p.get("tenant_id") == tenant_id and p.get("status") == "active"]
    if not candidates:
        _persist_update(tc["id"], status="failed", http_status=503, error_code="NO_PROVIDER_KEY", error_message="No active provider key available", provider_endpoint="amap/distance")
        return _err("UNAUTHORIZED", "No provider key available to serve request")

    # Weighted choice by weight (>=0)
    weights = [max(0, int(p.get("weight", 0)) if isinstance(p.get("weight", 0), int) else 0) for p in candidates]
    if sum(weights) == 0:
        weights = [1] * len(candidates)
    pk = random.choices(candidates, weights=weights, k=1)[0]

    _persist_update(tc["id"], status="dispatched", provider_key_id=pk.get("id"), provider_endpoint="amap/distance")

    results = []
    for oc, oc_str in zip(parsed_origins, norm_origins):
        d = _haversine_m(oc, parsed_dest)
        if d >= 20000000:  # unreachable guard, practically never
            results.append({"origin": oc_str, "destination": norm_dest, "status": "NOT_FOUND"})
            continue
        if type == "distance":
            results.append({"origin": oc_str, "destination": norm_dest, "distance_m": int(round(d)), "status": "OK"})
        elif type == "walking":
            duration = d / 1.2
            results.append({"origin": oc_str, "destination": norm_dest, "distance_m": int(round(d)), "duration_s": int(round(duration)), "status": "OK"})
        else:  # driving
            duration = d / 8.0
            results.append({"origin": oc_str, "destination": norm_dest, "distance_m": int(round(d)), "duration_s": int(round(duration)), "status": "OK"})

    response_body = {"type": type, "destination": norm_dest, "origins_count": len(norm_origins), "results": results}
    _persist_update(tc["id"], status="succeeded", http_status=200, response_body=response_body, provider_request_id=None)

    return {
        "results": results,
        "type": type,
        "origins_count": len(norm_origins),
        "destination": norm_dest,
        "meta": {"cached": False, "tool_call_id": tc["id"]},
    }

def maps_text_search(keywords, city=None, page=None, page_size=None, **_extra):
    import json, os, datetime, time, hashlib, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _sha(s):
        return hashlib.sha256(s.encode("utf-8")).hexdigest()

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randrange(100000, 999999)}"

    def _pick_auth_context():
        tenants = _load("tenants.json")
        api_keys = _load("api_keys.json")
        provider_keys = _load("amap_provider_keys.json")

        viable = []
        for t in tenants:
            if t.get("status") != "active":
                continue
            t_id = t.get("id")
            if not isinstance(t_id, str) or not t_id:
                continue
            pks = [p for p in provider_keys if p.get("tenant_id") == t_id and p.get("status") == "active"]
            if not pks:
                continue
            aks = [a for a in api_keys if a.get("tenant_id") == t_id and a.get("status") == "active"]
            viable.append((t, aks[0] if aks else None, pks))
        if not viable:
            for t in tenants:
                if t.get("status") == "active" and isinstance(t.get("id"), str) and t.get("id"):
                    t_id = t["id"]
                    aks = [a for a in api_keys if a.get("tenant_id") == t_id and a.get("status") == "active"]
                    return (t, aks[0] if aks else None, [])
            return None
        viable.sort(key=lambda x: (int(x[0].get("daily_request_quota", 0)), str(x[0].get("name", ""))), reverse=True)
        return viable[0]

    def _align_window(dt, gran):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if gran == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _get_or_create_rollup(usage, tenant_id, api_key_id, tool_name, gran, window_start_iso):
        for r in usage:
            if (
                r.get("tenant_id") == tenant_id
                and r.get("api_key_id") == api_key_id
                and r.get("tool_name") == tool_name
                and r.get("window_granularity") == gran
                and r.get("window_start") == window_start_iso
            ):
                return r
        now = _now()
        r = {
            "id": "ur_" + _sha(f"{tenant_id}|{api_key_id or ''}|{tool_name or ''}|{gran}|{window_start_iso}")[:24],
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "window_start": window_start_iso,
            "window_granularity": gran,
            "requests_count": 0,
            "success_count": 0,
            "error_count": 0,
            "rate_limited_count": 0,
            "billed_units": 0,
            "created_at": now,
            "updated_at": now,
        }
        usage.append(r)
        return r

    def _persist_call_and_usage(tool_call, status, http_status=None, response_body=None, err_code=None, err_msg=None, provider_key_id=None, provider_endpoint=None, billed_units=1, start_ts=None):
        tool_calls = _load("tool_calls.json")
        usage = _load("usage_rollups.json")
        api_keys = _load("api_keys.json")
        tenants = _load("tenants.json")

        now_dt = datetime.datetime.utcnow()
        now_iso = _now()
        if start_ts is None:
            start_ts = time.time()

        # update tool_call row in-place
        updated = False
        transitions = {
            "received": {"validated", "failed", "rate_limited"},
            "validated": {"cache_hit", "dispatched", "failed", "rate_limited"},
            "cache_hit": {"succeeded"},
            "dispatched": {"succeeded", "failed"},
            "succeeded": set(),
            "failed": set(),
            "rate_limited": set(),
        }
        for row in tool_calls:
            if row.get("id") == tool_call["id"]:
                old = row.get("status")
                if status != old:
                    if status not in transitions.get(old, set()):
                        row["status"] = "failed"
                        row["error_code"] = "INVALID_TRANSITION"
                        row["error_message"] = f"Illegal transition {old} -> {status}"
                    else:
                        row["status"] = status
                row["http_status"] = http_status
                row["provider_key_id"] = provider_key_id
                row["provider_endpoint"] = provider_endpoint
                row["provider_request_id"] = None
                row["billed_units"] = int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1
                row["duration_ms"] = int(round((time.time() - start_ts) * 1000))
                row["updated_at"] = now_iso

                row["response_body"] = response_body
                row["error_code"] = err_code
                row["error_message"] = err_msg

                if row["status"] != "succeeded":
                    row["response_body"] = None
                if row["status"] not in ("failed", "rate_limited"):
                    row["error_code"] = None
                    row["error_message"] = None
                updated = True
                break

        if not updated:
            return _err("NOT_FOUND", "tool_call not found for update")

        tenant_id = tool_call["tenant_id"]
        api_key_id = tool_call.get("api_key_id")

        # api_key last_used_at on success
        if status == "succeeded" and api_key_id:
            for a in api_keys:
                if a.get("id") == api_key_id:
                    a["last_used_at"] = now_iso
                    a["updated_at"] = now_iso
                    break

        minute_start = _align_window(now_dt, "minute").replace(microsecond=0).isoformat() + "Z"
        day_start = _align_window(now_dt, "day").replace(microsecond=0).isoformat() + "Z"
        month_start = _align_window(now_dt, "month").replace(microsecond=0).isoformat() + "Z"

        def bump(api_key_scope):
            r_min = _get_or_create_rollup(usage, tenant_id, api_key_scope, "maps_text_search", "minute", minute_start)
            r_min["requests_count"] += 1
            if status == "succeeded":
                r_min["success_count"] += 1
            elif status == "rate_limited":
                r_min["rate_limited_count"] += 1
            else:
                r_min["error_count"] += 1
            r_min["billed_units"] += int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1
            r_min["updated_at"] = now_iso

            r_day = _get_or_create_rollup(usage, tenant_id, api_key_scope, None, "day", day_start)
            r_day["requests_count"] += 1
            if status == "succeeded":
                r_day["success_count"] += 1
            elif status == "rate_limited":
                r_day["rate_limited_count"] += 1
            else:
                r_day["error_count"] += 1
            r_day["billed_units"] += int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1
            r_day["updated_at"] = now_iso

            r_mon = _get_or_create_rollup(usage, tenant_id, api_key_scope, None, "month", month_start)
            r_mon["requests_count"] += 1
            if status == "succeeded":
                r_mon["success_count"] += 1
            elif status == "rate_limited":
                r_mon["rate_limited_count"] += 1
            else:
                r_mon["error_count"] += 1
            r_mon["billed_units"] += int(billed_units) if isinstance(billed_units, int) and billed_units >= 0 else 1
            r_mon["updated_at"] = now_iso

        bump(api_key_id)
