        items = pois[start_idx:end_idx] if start_idx < total else []

        response_body = {"count": total, "page": page, "page_size": page_size, "pois": items}
        _persist_call_and_usage(tool_call, "succeeded", http_status=200, response_body=response_body, provider_key_id=pk.get("id"), provider_endpoint="amap/text_search", start_ts=start_ts)

