    monthly_q = int(tenant.get("monthly_request_quota", 0)) if isinstance(tenant.get("monthly_request_quota"), int) else 0
    if daily_q >= 0 and _tenant_total("day", day_start) >= daily_q:
        _persist_call_and_usage(tool_call, "rate_limited", http_status=429, err_code="QUOTA_DAILY", err_msg="Tenant daily quota exceeded", start_ts=start_ts)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
    if monthly_q >= 0 and _tenant_total("month", month_start) >= monthly_q:
        _persist_call_and_usage(tool_call, "rate_limited", http_status=429, err_code="QUOTA_MONTHLY", err_msg="Tenant monthly quota exceeded", start_ts=start_ts)
        return _err("QUOTA_EXCEEDED", "Monthly quota exceeded")

    _persist_call_and_usage(tool_call, "validated", start_ts=start_ts)

    tool_calls = _load("tool_calls.json")
    cached = None
    for row in reversed(tool_calls):
        if row.get("cache_key") == cache_key and row.get("status") == "succeeded" and isinstance(row.get("response_body"), dict):
            cached = row
            break

    if cached:
        _persist_call_and_usage(tool_call, "cache_hit", provider_endpoint=None, provider_key_id=None, start_ts=start_ts)
        resp = cached.get("response_body") or {}
        _persist_call_and_usage(tool_call, "succeeded", http_status=200, response_body=resp, provider_endpoint=None, provider_key_id=None, start_ts=start_ts)
    else:
        provider_keys = _load("amap_provider_keys.json")
        candidates = [p for p in provider_keys if p.get("tenant_id") == tool_call["tenant_id"] and p.get("status") == "active"]
        if not candidates:
            _persist_call_and_usage(tool_call, "failed", http_status=503, err_code="NO_PROVIDER_KEY", err_msg="No active provider key available", provider_endpoint="amap/around_search", start_ts=start_ts)
            return _err("UNAUTHORIZED", "No provider key available to serve request")
        weights = [max(0, int(p.get("weight", 0)) if isinstance(p.get("weight", 0), int) else 0) for p in candidates]
        if sum(weights) == 0:
            weights = [1] * len(candidates)
        pk = random.choices(candidates, weights=weights, k=1)[0]

        _persist_call_and_usage(tool_call, "dispatched", provider_key_id=pk.get("id"), provider_endpoint="amap/around_search", start_ts=start_ts)

        loc = _parse_coord(loc_norm)
        seed = int(_sha(f"{loc_norm}|{radius}|{kw_norm or ''}")[:8], 16)
        rng = random.Random(seed)

        # Total results influenced by radius (cap) and keyword existence
        base = min(80, max(0, int(radius / 50)))
        total = rng.randint(0, base if kw_norm else min(120, base + 30))

        pois = []
        for i in range(total):
            # scatter around within radius (rough degrees)
            ang = rng.random() * 2 * math.pi
            r_m = rng.random() * radius
            dlat = (r_m * math.cos(ang)) / 111000.0
            dlng = (r_m * math.sin(ang)) / (111000.0 * max(0.2, math.cos(math.radians(loc[1]))))
            lng = loc[0] + dlng
            lat = loc[1] + dlat
            pois.append(
                {
                    "poi_id": "B0" + _sha(f"{loc_norm}|{radius}|{kw_norm or ''}|{i}")[:14].upper(),
                    "name": (keywords.strip() + "-") if isinstance(keywords, str) and keywords.strip() else "POI-" + "" + str(i + 1),
                    "address": f"Nearby {rng.randint(1, 999)}",
                    "location": f"{lng:.6f},{lat:.6f}",
                    "distance_m": int(r_m),
                    "raw": {"source": "amap_simulated"},
                }
            )

        start_idx = (page - 1) * page_size
        end_idx = start_idx + page_size
        items = pois[start_idx:end_idx] if start_idx < total else []

        response_body = {"count": total, "page": page, "page_size": page_size, "pois": items, "center": loc_norm, "radius": radius}
        _persist_call_and_usage(tool_call, "succeeded", http_status=200, response_body=response_body, provider_key_id=pk.get("id"), provider_endpoint="amap/around_search", start_ts=start_ts)

    tool_calls = _load("tool_calls.json")
    row = next((r for r in tool_calls if r.get("id") == tool_call["id"]), None)
    resp = (row or {}).get("response_body") or {"count": 0, "page": page, "page_size": page_size, "pois": [], "center": loc_norm, "radius": radius}
    total = int(resp.get("count", 0)) if isinstance(resp.get("count", 0), int) else 0
    has_more = page * page_size < total
    return {
        "pois": resp.get("pois", []),
        "center": resp.get("center", loc_norm),
        "radius": resp.get("radius", radius),
        "page": page,
        "page_size": page_size,
        "total": total,
        "has_more": has_more,
        "next_page": (page + 1) if has_more else None,
        "meta": {"tool_call_id": tool_call["id"], "cached": (row or {}).get("provider_endpoint") is None},
    }

def mcp_whoami(mcp_session_id, api_key, include_usage=None, usage_window_granularities=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    # ---- validate inputs ----
    if not isinstance(mcp_session_id, str) or not mcp_session_id.strip():
        return _err("VALIDATION_ERROR", "mcp_session_id must be a non-empty string")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if include_usage is None:
        include_usage = True
    if not isinstance(include_usage, bool):
        return _err("VALIDATION_ERROR", "include_usage must be a boolean")
    if usage_window_granularities is None:
        usage_window_granularities = ["minute", "day", "month"]
    if (not isinstance(usage_window_granularities, list)
        or any((not isinstance(x, str)) for x in usage_window_granularities)):
        return _err("VALIDATION_ERROR", "usage_window_granularities must be an array of strings")
    allowed_grans = {"minute", "day", "month"}
    if any(g not in allowed_grans for g in usage_window_granularities):
        return _err("VALIDATION_ERROR", "usage_window_granularities contains invalid value", allowed=list(sorted(allowed_grans)))

    tool_calls = _load("tool_calls.json")
    api_keys = _load("api_keys.json")
    tenants = _load("tenants.json")
    usage_rollups = _load("usage_rollups.json")

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, datetime.datetime):
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        if isinstance(dt, str):
            return dt
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _floor(dt, gran):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if gran == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if gran == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return None

    def _gen_id(prefix):
        h = hashlib.sha256(f"{prefix}:{now.isoformat()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _authenticate_api_key(api_key_plain):
        # NOTE: store only has hash; caller provides plaintext. We can't validate by hash comparison.
        # As per contract, authenticate by matching client-visible value or id. We have key_prefix + id.
        # We'll accept either an exact api_keys.id match, or a key_prefix match if unique.
        candidates = []
        for r in api_keys:
            if not isinstance(r, dict):
                continue
            if r.get("id") == api_key_plain:
                candidates.append(r)
            elif r.get("key_prefix") == api_key_plain:
                candidates.append(r)
        # Prefer exact id match; otherwise require uniqueness for prefix match.
        exact = [c for c in candidates if c.get("id") == api_key_plain]
        if exact:
            return exact[0]
        if len(candidates) == 1:
            return candidates[0]
        return None

    def _log_call(tenant_id, api_key_id, status, response_body=None, error_code=None, error_message=None, http_status=None):
        duration_ms = int(round((time.time() - t0) * 1000))
        row = {
            "id": _gen_id("tc"),
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "provider_key_id": None,
            "mcp_session_id": mcp_session_id,
            "tool_name": "mcp_whoami",
            "status": status,
            "request_params": {
                "mcp_session_id": mcp_session_id,
                "api_key": api_key,
                "include_usage": include_usage,
                "usage_window_granularities": usage_window_granularities,
            },
            "normalized_params": {"include_usage": include_usage, "usage_window_granularities": usage_window_granularities},
            "cache_key": None,
            "cache_ttl_seconds": None,
            "http_status": http_status,
            "provider_endpoint": None,
            "provider_request_id": None,
            "response_body": response_body,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms if duration_ms >= 0 else 0,
            "billed_units": 1,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # ---- auth resolve ----
    ak = _authenticate_api_key(api_key.strip())
    if not ak:
        # no working combination -> UNAUTHORIZED
        _log_call(tenant_id="unknown", api_key_id=None, status="failed",
                  response_body=None, error_code="UNAUTHORIZED", error_message="Invalid or missing API key", http_status=401)
        return _err("UNAUTHORIZED", "Invalid or missing API key")

    tenant_id = ak.get("tenant_id")
    tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == tenant_id), None)
    if not tenant:
        _log_call(tenant_id=tenant_id or "unknown", api_key_id=ak.get("id"), status="failed",
                  response_body=None, error_code="NOT_FOUND", error_message="Tenant not found for API key", http_status=401)
        return _err("UNAUTHORIZED", "Tenant not found for API key")

    if ak.get("status") != "active":
        _log_call(tenant_id=tenant_id, api_key_id=ak.get("id"), status="failed",
                  response_body=None, error_code="FORBIDDEN", error_message="API key revoked", http_status=403)
        return _err("UNAUTHORIZED", "API key revoked")  # tool description: UNAUTHORIZED/FORBIDDEN; allowed codes list lacks FORBIDDEN

    if tenant.get("status") != "active":
        _log_call(tenant_id=tenant_id, api_key_id=ak.get("id"), status="failed",
                  response_body=None, error_code="FORBIDDEN", error_message=f"Tenant status is {tenant.get('status')}", http_status=403)
        return _err("UNAUTHORIZED", f"Tenant is not active (status={tenant.get('status')})")

    # ---- compute usage summary ----
    usage_summary = None
    if include_usage:
        # Aggregate from usage_rollups for this tenant+api_key_id, for requested granularities.
        # Also compute quota remaining using tenant quotas for day/month and key rpm for minute.
        rpm_limit = ak.get("requests_per_minute_limit", 0)
        if not isinstance(rpm_limit, int) or rpm_limit < 0:
            rpm_limit = 0
        daily_quota = tenant.get("daily_request_quota", 0)
        monthly_quota = tenant.get("monthly_request_quota", 0)
        if not isinstance(daily_quota, int) or daily_quota < 0:
            daily_quota = 0
        if not isinstance(monthly_quota, int) or monthly_quota < 0:
            monthly_quota = 0

        cur_min = _floor(now, "minute")
        cur_day = _floor(now, "day")
        cur_month = _floor(now, "month")

        def _sum_rollups(gran, window_start, api_key_scope):
            # api_key_scope: "key" or "tenant"
            req = succ = errc = rlc = billed = 0
            for r in usage_rollups:
                if not isinstance(r, dict):
                    continue
                if r.get("tenant_id") != tenant_id:
                    continue
                if r.get("window_granularity") != gran:
                    continue
                ws = _parse_dt(r.get("window_start"))
                if not ws or ws != window_start:
                    continue
                if api_key_scope == "key":
                    if r.get("api_key_id") != ak.get("id"):
                        continue
                else:
                    if r.get("api_key_id") is not None:
                        continue
                req += int(r.get("requests_count") or 0)
                succ += int(r.get("success_count") or 0)
                errc += int(r.get("error_count") or 0)
                rlc += int(r.get("rate_limited_count") or 0)
                billed += int(r.get("billed_units") or 0)
            return {"requests": req, "success": succ, "error": errc, "rate_limited": rlc, "billed_units": billed}

        usage_summary = {"windows": {}}
        for g in usage_window_granularities:
            if g == "minute":
                key_counts = _sum_rollups("minute", cur_min, "key")
                remaining = None
                if rpm_limit > 0:
                    remaining = max(0, rpm_limit - key_counts["requests"])
                usage_summary["windows"]["minute"] = {
                    "window_start": _iso(cur_min),
                    "scope": "api_key",
                    "limit": rpm_limit,
                    "remaining": remaining,
                    "counts": key_counts,
                }
            elif g == "day":
                tenant_counts = _sum_rollups("day", cur_day, "tenant")
                remaining = None
                if daily_quota > 0:
                    remaining = max(0, daily_quota - tenant_counts["requests"])
                usage_summary["windows"]["day"] = {
                    "window_start": _iso(cur_day),
                    "scope": "tenant",
                    "limit": daily_quota,
                    "remaining": remaining,
                    "counts": tenant_counts,
                }
            elif g == "month":
                tenant_counts = _sum_rollups("month", cur_month, "tenant")
                remaining = None
                if monthly_quota > 0:
                    remaining = max(0, monthly_quota - tenant_counts["requests"])
                usage_summary["windows"]["month"] = {
                    "window_start": _iso(cur_month),
                    "scope": "tenant",
                    "limit": monthly_quota,
                    "remaining": remaining,
                    "counts": tenant_counts,
                }

    # ---- update last_used_at on success ----
    ak_id = ak.get("id")
    for i, r in enumerate(api_keys):
        if isinstance(r, dict) and r.get("id") == ak_id:
            api_keys[i] = dict(r)
            api_keys[i]["last_used_at"] = _iso(now)
            api_keys[i]["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    resp = {
        "identity": {
            "tenant": {"id": tenant_id, "name": tenant.get("name"), "status": tenant.get("status"), "default_region": tenant.get("default_region")},
            "api_key": {"id": ak_id, "status": ak.get("status"), "key_prefix": ak.get("key_prefix")},
        },
        "capabilities": {
            "tools": [
                "maps_regeocode", "maps_geo", "maps_ip_location", "maps_weather",
                "maps_bicycling_by_address", "maps_bicycling_by_coordinates",
                "maps_direction_walking_by_address", "maps_direction_walking_by_coordinates",
                "maps_direction_driving_by_address", "maps_direction_driving_by_coordinates",
                "maps_direction_transit_integrated_by_address", "maps_direction_transit_integrated_by_coordinates",
                "maps_distance", "maps_text_search", "maps_around_search", "maps_search_detail",
                "admin_tool_calls_list", "admin_tool_calls_get", "admin_usage_rollups_list"
            ]
        },
        "usage": usage_summary,
        "server_time": _iso(now),
    }

    _log_call(tenant_id=tenant_id, api_key_id=ak_id, status="succeeded", response_body=resp, http_status=200)
    return resp

def admin_tool_calls_list(mcp_session_id, api_key, tenant_id=None, tool_name=None, status=None, created_from=None, created_to=None, page=None, page_size=None, sort=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    # ---- validate ----
    if not isinstance(mcp_session_id, str) or not mcp_session_id.strip():
        return _err("VALIDATION_ERROR", "mcp_session_id must be a non-empty string")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if tenant_id is not None and (not isinstance(tenant_id, str) or not tenant_id.strip()):
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string when provided")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided")
    allowed_status = {"received", "validated", "cache_hit", "dispatched", "succeeded", "failed", "rate_limited"}
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "status is invalid", allowed=list(sorted(allowed_status)))
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if sort is None:
        sort = "created_at_desc"
    if sort not in {"created_at_desc", "created_at_asc"}:
        return _err("VALIDATION_ERROR", "sort is invalid", allowed=["created_at_desc", "created_at_asc"])

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    dt_from = _parse_dt(created_from) if created_from is not None else None
    if created_from is not None and dt_from is None:
        return _err("VALIDATION_ERROR", "created_from must be ISO8601 date-time")
    dt_to = _parse_dt(created_to) if created_to is not None else None
    if created_to is not None and dt_to is None:
        return _err("VALIDATION_ERROR", "created_to must be ISO8601 date-time")
    if dt_from and dt_to and dt_to <= dt_from:
        return _err("VALIDATION_ERROR", "created_to must be greater than created_from")

    tool_calls = _load("tool_calls.json")
    api_keys = _load("api_keys.json")
    tenants = _load("tenants.json")

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        h = hashlib.sha256(f"{prefix}:{now.isoformat()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _authenticate_api_key(api_key_plain):
        candidates = []
        for r in api_keys:
            if not isinstance(r, dict):
                continue
            if r.get("id") == api_key_plain:
                candidates.append(r)
            elif r.get("key_prefix") == api_key_plain:
                candidates.append(r)
        exact = [c for c in candidates if c.get("id") == api_key_plain]
        if exact:
            return exact[0]
        if len(candidates) == 1:
            return candidates[0]
        return None

    def _log(status_row, tenant_for_log, api_key_id_for_log, response_body=None, error_code=None, error_message=None, http_status=None):
        duration_ms = int(round((time.time() - t0) * 1000))
        row = {
            "id": _gen_id("tc"),
            "tenant_id": tenant_for_log,
            "api_key_id": api_key_id_for_log,
            "provider_key_id": None,
            "mcp_session_id": mcp_session_id,
            "tool_name": "admin_tool_calls_list",
            "status": status_row,
            "request_params": {
                "mcp_session_id": mcp_session_id,
                "api_key": api_key,
                "tenant_id": tenant_id,
                "tool_name": tool_name,
                "status": status,
                "created_from": created_from,
                "created_to": created_to,
                "page": page,
                "page_size": page_size,
                "sort": sort,
            },
            "normalized_params": {
                "tenant_id": tenant_id,
                "tool_name": tool_name,
                "status": status,
                "created_from": created_from,
                "created_to": created_to,
                "page": page,
                "page_size": page_size,
                "sort": sort,
            },
            "cache_key": None,
            "cache_ttl_seconds": None,
            "http_status": http_status,
            "provider_endpoint": None,
            "provider_request_id": None,
            "response_body": response_body,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms if duration_ms >= 0 else 0,
            "billed_units": 1,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    # ---- auth ----
    ak = _authenticate_api_key(api_key.strip())
    if not ak:
        _log("failed", "unknown", None, error_code="UNAUTHORIZED", error_message="Invalid or missing API key", http_status=401)
        return _err("UNAUTHORIZED", "Invalid or missing API key")
    if ak.get("status") != "active":
        _log("failed", ak.get("tenant_id") or "unknown", ak.get("id"), error_code="FORBIDDEN", error_message="API key revoked", http_status=403)
        return _err("UNAUTHORIZED", "API key revoked")
    caller_tenant_id = ak.get("tenant_id")
    caller_tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == caller_tenant_id), None)
    if not caller_tenant:
        _log("failed", caller_tenant_id or "unknown", ak.get("id"), error_code="NOT_FOUND", error_message="Tenant not found for API key", http_status=401)
        return _err("UNAUTHORIZED", "Tenant not found for API key")

    target_tenant_id = tenant_id.strip() if isinstance(tenant_id, str) and tenant_id.strip() else caller_tenant_id
    if target_tenant_id != caller_tenant_id:
        _log("failed", caller_tenant_id, ak.get("id"), error_code="FORBIDDEN", error_message="API key does not belong to target tenant", http_status=403)
        return _err("UNAUTHORIZED", "No permission for target tenant")

    # tenant suspended/deleted: still allow reads
    target_tenant = caller_tenant

    # ---- filter ----
    def _parse_created(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return None
        dt = _parse_dt(s)
        return dt

    filtered = []
    for r in tool_calls:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != target_tenant_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        cdt = _parse_created(r)
        if dt_from and (cdt is None or cdt < dt_from):
            continue
        if dt_to and (cdt is None or cdt >= dt_to):
            continue
        filtered.append(r)

    reverse = (sort == "created_at_desc")
    filtered.sort(key=lambda x: (_parse_created(x) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=reverse)

    total = len(filtered)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = filtered[start:end]
    has_more = end < total

    # Hide sensitive fields if tenant not active (rule says hide sensitive; none of the stored sensitive ciphertext appears here).
    # We'll keep provider_key_id but not return anything about provider key itself (not present anyway).
    def _sanitize(row):
        out = dict(row)
        # Never expose requester's api_key in request_params if it ever got stored
        rp = out.get("request_params")
        if isinstance(rp, dict) and "api_key" in rp:
            rp2 = dict(rp)
            rp2["api_key"] = "***"
            out["request_params"] = rp2
        return out

    resp = {
        "data": [_sanitize(r) for r in page_rows],
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "sort": sort,
            "tenant": {"id": target_tenant_id, "status": target_tenant.get("status")},
        },
    }

    _log("succeeded", target_tenant_id, ak.get("id"), response_body=resp, http_status=200)
    return resp

def admin_tool_calls_get(mcp_session_id, api_key, id, **_extra):
    import json, os, datetime, time, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    tool_name = "admin_tool_calls_get"

    # ---- validate inputs ----
    if not isinstance(mcp_session_id, str) or not mcp_session_id.strip():
        return _err("VALIDATION_ERROR", "mcp_session_id must be a non-empty string")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    tool_calls = _load("tool_calls.json")
    usage_rollups = _load("usage_rollups.json")

    def _isoz(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _floor(dt, gran):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if gran == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if gran == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        seed = f"{prefix}_{now_dt.isoformat()}_{os.getpid()}_{time.time_ns()}"
        suf = hashlib.sha1(seed.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{suf}"

    def _find_api_key_row(api_key_value):
        # Authenticate by id or by key_prefix (client-visible). Never by key_hash.
        for r in api_keys:
            if r.get("id") == api_key_value:
                return r
        for r in api_keys:
            kp = r.get("key_prefix")
            if isinstance(kp, str) and api_key_value.startswith(kp):
                return r
        return None

    def _ensure_rollup(tenant_id, api_key_id, tool, gran, window_start_iso):
        for r in usage_rollups:
            if (
                r.get("tenant_id") == tenant_id
                and r.get("api_key_id") == api_key_id
                and r.get("tool_name") == tool
                and r.get("window_granularity") == gran
                and r.get("window_start") == window_start_iso
            ):
                return r
        r = {
            "id": _gen_id("amap_usa"),
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "tool_name": tool,
            "window_start": window_start_iso,
            "window_granularity": gran,
            "requests_count": 0,
            "success_count": 0,
            "error_count": 0,
            "rate_limited_count": 0,
            "billed_units": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_rollups.append(r)
        return r

    # ---- resolve auth/context (search for a working combination) ----
    ak = _find_api_key_row(api_key.strip())
    if not ak or ak.get("status") != "active":
        # audit as failed even if unauthorized
        duration_ms = max(0, int((time.time() - t0) * 1000))
        # best-effort tenant for logging: none
        tc_row = {
            "id": _gen_id("amap_call"),
            "tenant_id": None,
            "api_key_id": ak.get("id") if isinstance(ak, dict) else None,
            "provider_key_id": None,
            "mcp_session_id": mcp_session_id,
            "tool_name": "maps_text_search",  # placeholder within enum not available; avoid invalid enum? can't.
        }
        # Cannot write invalid row due to schema enums; instead, only update rollups if possible.
        return _err("UNAUTHORIZED", "api_key is missing, inactive, or not recognized")

    tenant_id = ak.get("tenant_id")
    tenant = None
    for t in tenants:
        if t.get("id") == tenant_id:
            tenant = t
            break
    if not tenant:
        return _err("UNAUTHORIZED", "api_key has no valid tenant context", api_key_id=ak.get("id"), tenant_id=tenant_id)

    # ---- locate tool_call record ----
    row = None
    for r in tool_calls:
        if r.get("id") == id:
            row = r
            break

    # ---- record observable dynamics (reads included) ----
    # We record this admin read as a tool_call audit row using the closest available enum tool_name.
    # Since schema tool_name enum does not include admin_* tools, we cannot persist admin_tool_calls_get
    # directly into tool_calls without violating enum. We therefore record to usage_rollups only.
    # (tool_calls collection is for map tools only.)
    minute_ws = _isoz(_floor(now_dt, "minute"))
    hour_ws = _isoz(_floor(now_dt, "hour"))
    day_ws = _isoz(_floor(now_dt, "day"))
    month_ws = _isoz(_floor(now_dt, "month"))

    # attribute to a synthetic tool_name=None rollup (allowed) at tenant and api_key level
    for (api_key_id, tool_dim) in ((None, None), (ak.get("id"), None)):
        for gran, ws in (("minute", minute_ws), ("hour", hour_ws), ("day", day_ws), ("month", month_ws)):
            rr = _ensure_rollup(tenant.get("id"), api_key_id, tool_dim, gran, ws)
            rr["requests_count"] = int(rr.get("requests_count") or 0) + 1
            rr["success_count"] = int(rr.get("success_count") or 0) + 1
            rr["updated_at"] = now_iso

    _save("usage_rollups.json", usage_rollups)

    # ---- authorization: must belong to same tenant ----
    if not row:
        return _err("NOT_FOUND", "tool_call not found", id=id)

    if row.get("tenant_id") != tenant.get("id"):
        return _err("UNAUTHORIZED", "api_key is not authorized to read this tool_call", id=id, tenant_id=row.get("tenant_id"))

    duration_ms = max(0, int((time.time() - t0) * 1000))
    return {
        "tool_call": row,
        "meta": {
            "requested_at": now_iso,
            "duration_ms": duration_ms,
            "tenant_id": tenant.get("id"),
            "api_key_id": ak.get("id"),
            "mcp_session_id": mcp_session_id,
        },
    }

def admin_usage_rollups_list(mcp_session_id, api_key, tenant_id=None, api_key_id=None, tool_name=None, window_granularity=None, window_start_from=None, window_start_to=None, page=None, page_size=None, sort=None, **_extra):
    import json, os, datetime, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    if not isinstance(mcp_session_id, str) or not mcp_session_id.strip():
        return _err("VALIDATION_ERROR", "mcp_session_id must be a non-empty string")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if tenant_id is not None and (not isinstance(tenant_id, str) or not tenant_id.strip()):
        return _err("VALIDATION_ERROR", "tenant_id must be a non-empty string when provided")
    if api_key_id is not None and (not isinstance(api_key_id, str) or not api_key_id.strip()):
        return _err("VALIDATION_ERROR", "api_key_id must be a non-empty string when provided")
    if tool_name is not None and (not isinstance(tool_name, str) or not tool_name.strip()):
        return _err("VALIDATION_ERROR", "tool_name must be a non-empty string when provided")
    allowed_gran = {"minute", "hour", "day", "month"}
    if window_granularity is not None and window_granularity not in allowed_gran:
        return _err("VALIDATION_ERROR", "window_granularity is invalid", allowed=list(sorted(allowed_gran)))
    if page is None:
        page = 1
    if page_size is None:
        page_size = 50
    if not isinstance(page, int) or page < 1:
        return _err("VALIDATION_ERROR", "page must be an integer >= 1")
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200")
    if sort is None:
        sort = "window_start_desc"
    if sort not in {"window_start_desc", "window_start_asc"}:
        return _err("VALIDATION_ERROR", "sort is invalid", allowed=["window_start_desc", "window_start_asc"])

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            s2 = s.strip()
            if s2.endswith("Z"):
                s2 = s2[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    dt_from = _parse_dt(window_start_from) if window_start_from is not None else None
    if window_start_from is not None and dt_from is None:
        return _err("VALIDATION_ERROR", "window_start_from must be ISO8601 date-time")
    dt_to = _parse_dt(window_start_to) if window_start_to is not None else None
    if window_start_to is not None and dt_to is None:
        return _err("VALIDATION_ERROR", "window_start_to must be ISO8601 date-time")
    if dt_from and dt_to and dt_to <= dt_from:
        return _err("VALIDATION_ERROR", "window_start_to must be greater than window_start_from")

    usage_rollups = _load("usage_rollups.json")
    api_keys = _load("api_keys.json")
    tenants = _load("tenants.json")
    tool_calls = _load("tool_calls.json")

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        h = hashlib.sha256(f"{prefix}:{now.isoformat()}:{os.getpid()}:{time.time_ns()}".encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{h}"

    def _authenticate_api_key(api_key_plain):
        candidates = []
        for r in api_keys:
            if not isinstance(r, dict):
                continue
            if r.get("id") == api_key_plain:
                candidates.append(r)
            elif r.get("key_prefix") == api_key_plain:
                candidates.append(r)
        exact = [c for c in candidates if c.get("id") == api_key_plain]
        if exact:
            return exact[0]
        if len(candidates) == 1:
            return candidates[0]
        return None

    def _log(status_row, tenant_for_log, api_key_id_for_log, response_body=None, error_code=None, error_message=None, http_status=None):
        duration_ms = int(round((time.time() - t0) * 1000))
        row = {
            "id": _gen_id("tc"),
            "tenant_id": tenant_for_log,
            "api_key_id": api_key_id_for_log,
            "provider_key_id": None,
            "mcp_session_id": mcp_session_id,
            "tool_name": "admin_usage_rollups_list",
            "status": status_row,
            "request_params": {
                "mcp_session_id": mcp_session_id,
                "api_key": api_key,
                "tenant_id": tenant_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "window_granularity": window_granularity,
                "window_start_from": window_start_from,
                "window_start_to": window_start_to,
                "page": page,
                "page_size": page_size,
                "sort": sort,
            },
            "normalized_params": {
                "tenant_id": tenant_id,
                "api_key_id": api_key_id,
                "tool_name": tool_name,
                "window_granularity": window_granularity,
                "window_start_from": window_start_from,
                "window_start_to": window_start_to,
                "page": page,
                "page_size": page_size,
                "sort": sort,
            },
            "cache_key": None,
            "cache_ttl_seconds": None,
            "http_status": http_status,
            "provider_endpoint": None,
            "provider_request_id": None,
            "response_body": response_body,
            "error_code": error_code,
            "error_message": error_message,
            "duration_ms": duration_ms if duration_ms >= 0 else 0,
            "billed_units": 1,
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        tool_calls.append(row)
        _save("tool_calls.json", tool_calls)

    ak = _authenticate_api_key(api_key.strip())
    if not ak:
        _log("failed", "unknown", None, error_code="UNAUTHORIZED", error_message="Invalid or missing API key", http_status=401)
        return _err("UNAUTHORIZED", "Invalid or missing API key")
    if ak.get("status") != "active":
        _log("failed", ak.get("tenant_id") or "unknown", ak.get("id"), error_code="FORBIDDEN", error_message="API key revoked", http_status=403)
        return _err("UNAUTHORIZED", "API key revoked")

    caller_tenant_id = ak.get("tenant_id")
    caller_tenant = next((t for t in tenants if isinstance(t, dict) and t.get("id") == caller_tenant_id), None)
    if not caller_tenant:
        _log("failed", caller_tenant_id or "unknown", ak.get("id"), error_code="NOT_FOUND", error_message="Tenant not found for API key", http_status=401)
        return _err("UNAUTHORIZED", "Tenant not found for API key")

    target_tenant_id = tenant_id.strip() if isinstance(tenant_id, str) and tenant_id.strip() else caller_tenant_id
    if target_tenant_id != caller_tenant_id:
        _log("failed", caller_tenant_id, ak.get("id"), error_code="FORBIDDEN", error_message="API key does not belong to target tenant", http_status=403)
        return _err("UNAUTHORIZED", "No permission for target tenant")

    target_tenant = caller_tenant
    if not target_tenant:
        _log("failed", target_tenant_id, ak.get("id"), error_code="NOT_FOUND", error_message="Tenant not found", http_status=404)
        return _err("NOT_FOUND", "Tenant not found")

    if api_key_id is not None:
        # Ensure the requested api_key_id belongs to tenant
        ak_row = next((r for r in api_keys if isinstance(r, dict) and r.get("id") == api_key_id), None)
        if not ak_row:
            _log("failed", target_tenant_id, ak.get("id"), error_code="NOT_FOUND", error_message="api_key_id not found", http_status=404)
            return _err("NOT_FOUND", "api_key_id not found")
        if ak_row.get("tenant_id") != target_tenant_id:
            _log("failed", target_tenant_id, ak.get("id"), error_code="FORBIDDEN", error_message="api_key_id not in tenant", http_status=403)
            return _err("UNAUTHORIZED", "No permission for api_key_id")

    allowed_tools = {
        "maps_regeocode", "maps_geo", "maps_ip_location", "maps_weather",
        "maps_bicycling_by_address", "maps_bicycling_by_coordinates",
        "maps_direction_walking_by_address", "maps_direction_walking_by_coordinates",
        "maps_direction_driving_by_address", "maps_direction_driving_by_coordinates",
        "maps_direction_transit_integrated_by_address", "maps_direction_transit_integrated_by_coordinates",
        "maps_distance", "maps_text_search", "maps_around_search", "maps_search_detail",
    }
    if tool_name is not None and tool_name not in allowed_tools:
        return _err("VALIDATION_ERROR", "tool_name is invalid", allowed=list(sorted(allowed_tools)))

    def _parse_ws(r):
        s = r.get("window_start")
        if not isinstance(s, str):
            return None
        return _parse_dt(s)

    rows = []
    for r in usage_rollups:
        if not isinstance(r, dict):
            continue
        if r.get("tenant_id") != target_tenant_id:
            continue
        if api_key_id is not None:
            if r.get("api_key_id") != api_key_id:
                continue
        # If api_key_id not provided: show all rollups for tenant (including api_key_id null and non-null)
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if window_granularity is not None and r.get("window_granularity") != window_granularity:
            continue
        ws = _parse_ws(r)
        if dt_from and (ws is None or ws < dt_from):
            continue
        if dt_to and (ws is None or ws >= dt_to):
            continue
        rows.append(r)

    reverse = (sort == "window_start_desc")
    rows.sort(key=lambda x: (_parse_ws(x) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=reverse)

    total = len(rows)
    start = (page - 1) * page_size
    end = start + page_size
    page_rows = rows[start:end]
    has_more = end < total

    resp = {
        "data": page_rows,
        "meta": {
            "page": page,
            "page_size": page_size,
            "total": total,
            "has_more": has_more,
            "sort": sort,
            "tenant": {"id": target_tenant_id, "status": target_tenant.get("status")},
        },
    }

    _log("succeeded", target_tenant_id, ak.get("id"), response_body=resp, http_status=200)
    return resp

def admin_amap_provider_keys_create(mcp_session_id, api_key, tenant_id, label, provider_key, weight=None, status=None, **_extra):
    import json, os, datetime, time, hashlib, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    tool_calls = _load("tool_calls.json")
    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    provider_keys = _load("amap_provider_keys.json")
    usage_rollups = _load("usage_rollups.json")

    def _new_id(prefix):
        return f"{prefix}_{secrets.token_hex(12)}"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1]
            try:
                return datetime.datetime.fromisoformat(ss)
            except Exception:
                return None
        return None

    def _floor_window(dt, gran):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if gran == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if gran == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return None

    def _isoz(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _find_tenant(tid):
        for t in tenants:
            if t.get("id") == tid:
                return t
        return None

    def _resolve_api_key_for_tenant(api_key_plain, tenant):
        # Authenticate by matching a client-visible value: key_prefix OR id.
        # The store does not contain plaintext keys; do not compare against key_hash.
        if not isinstance(api_key_plain, str) or not api_key_plain.strip():
            return None
        needle = api_key_plain.strip()
        candidates = []
        for k in api_keys:
            if k.get("status") != "active":
                continue
            if k.get("tenant_id") != tenant.get("id"):
                continue
            if k.get("id") == needle:
                candidates.append(k)
                continue
            kp = k.get("key_prefix")
            if isinstance(kp, str) and kp and needle.startswith(kp):
                candidates.append(k)
        if not candidates:
            return None
        # Prefer exact id match
        for k in candidates:
            if k.get("id") == needle:
                return k
        return candidates[0]

    def _upsert_rollup(tenant_id, api_key_id, tool_name, granularity, window_start_dt):
        ws = _isoz(window_start_dt)
        for r in usage_rollups:
            if r.get("tenant_id") == tenant_id and r.get("api_key_id") == api_key_id and r.get("tool_name") == tool_name and r.get("window_granularity") == granularity and r.get("window_start") == ws:
                return r
        r = {
            "id": _new_id("ur"),
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "window_start": ws,
            "window_granularity": granularity,
            "requests_count": 0,
            "success_count": 0,
            "error_count": 0,
            "rate_limited_count": 0,
            "billed_units": 0,
            "created_at": now,
            "updated_at": now
        }
        usage_rollups.append(r)
        return r

    def _count_window_requests(tenant_id, api_key_id, granularity, window_start_dt):
        ws = _isoz(window_start_dt)
        total = 0
        for r in usage_rollups:
            if r.get("tenant_id") != tenant_id:
                continue
            if r.get("api_key_id") != api_key_id:
                continue
            if r.get("tool_name") is not None:
                continue  # tenant/api-key aggregate uses tool_name null
            if r.get("window_granularity") != granularity:
                continue
            if r.get("window_start") != ws:
                continue
            total += int(r.get("requests_count") or 0)
        return total

    def _log_tool_call(status, http_status=None, api_key_id=None, provider_key_id=None, error_code=None, error_message=None, response_body=None, billed_units=1):
        tc = {
            "id": _new_id("tc"),
            "tenant_id": tenant_id if isinstance(tenant_id, str) else None,
            "api_key_id": api_key_id,
            "provider_key_id": provider_key_id,
            "mcp_session_id": mcp_session_id,
            "tool_name": "admin_amap_provider_keys_create",
            "status": status,
            "request_params": {
                "mcp_session_id": mcp_session_id,
                "api_key": api_key,
                "tenant_id": tenant_id,
                "label": label,
                "provider_key": "***",  # do not store plaintext
                "weight": weight,
                "status": status_param
            },
            "normalized_params": {
                "tenant_id": tenant_id,
                "label": (label.strip() if isinstance(label, str) else label),
                "weight": weight_val,
                "status": status_param
            },
            "cache_key": None,
            "cache_ttl_seconds": None,
            "http_status": http_status,
            "provider_endpoint": None,
            "provider_request_id": None,
            "response_body": response_body if status == "succeeded" else None,
            "error_code": error_code if status in ("failed", "rate_limited") else None,
            "error_message": error_message if status in ("failed", "rate_limited") else None,
            "duration_ms": int((time.time() - start) * 1000),
            "billed_units": int(billed_units),
            "created_at": now,
            "updated_at": now
        }
        # Data integrity constraints
        if tc["response_body"] is not None and status != "succeeded":
            tc["response_body"] = None
        if (tc["error_code"] is not None or tc["error_message"] is not None) and status not in ("failed", "rate_limited"):
            tc["error_code"] = None
            tc["error_message"] = None
        tool_calls.append(tc)

        # Update rollups for observability/quota (admin calls count too)
        if isinstance(tenant_id, str) and tenant_id:
            dt_now = datetime.datetime.utcnow()
            for gran in ("minute", "day", "month"):
                wsdt = _floor_window(dt_now, gran)
                r_tenant = _upsert_rollup(tenant_id, None, None, gran, wsdt)
                r_tool = _upsert_rollup(tenant_id, None, "admin_amap_provider_keys_create", gran, wsdt)
                r_tenant["requests_count"] += 1
                r_tool["requests_count"] += 1
                if status == "succeeded":
                    r_tenant["success_count"] += 1
                    r_tool["success_count"] += 1
                elif status == "rate_limited":
                    r_tenant["rate_limited_count"] += 1
                    r_tool["rate_limited_count"] += 1
                else:
                    r_tenant["error_count"] += 1
                    r_tool["error_count"] += 1
                r_tenant["billed_units"] += int(billed_units)
                r_tool["billed_units"] += int(billed_units)
                r_tenant["updated_at"] = now
                r_tool["updated_at"] = now

    # Validate inputs
    status_param = status if status is not None else "active"
    if not isinstance(mcp_session_id, str) or not mcp_session_id.strip():
        return _err("VALIDATION_ERROR", "mcp_session_id is required and must be a non-empty string")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key is required and must be a non-empty string")
    if not isinstance(tenant_id, str) or not tenant_id.strip():
        return _err("VALIDATION_ERROR", "tenant_id is required and must be a non-empty string")
    if not isinstance(label, str) or not label.strip():
        return _err("VALIDATION_ERROR", "label is required and must be a non-empty string")
    if not isinstance(provider_key, str) or not provider_key.strip():
        return _err("VALIDATION_ERROR", "provider_key is required and must be a non-empty string")
    if status_param not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled")
    if weight is None:
        weight_val = 0
    else:
        if not isinstance(weight, int):
            return _err("VALIDATION_ERROR", "weight must be an integer >= 0")
        if weight < 0:
            return _err("VALIDATION_ERROR", "weight must be >= 0")
        weight_val = weight

    tenant = _find_tenant(tenant_id)
    if tenant is None:
        # still log tool call attempt (unknown tenant cannot attach rollups reliably)
        # Log with failed without tenant association to avoid fk issues: leave tenant_id None
        # But schema requires tenant_id non-null; so we cannot create tool_calls row if tenant unknown.
        return _err("NOT_FOUND", "tenant not found", tenant_id=tenant_id)

    # Tenant lifecycle gate (non-active => forbidden to create tool_calls / mutate config)
    if tenant.get("status") != "active":
        # Record attempt as failed (business says forbidden)
        _log_tool_call("failed", http_status=403, api_key_id=None, error_code="FORBIDDEN", error_message="tenant is not active", billed_units=1)
        _save("tool_calls.json", tool_calls)
        _save("usage_rollups.json", usage_rollups)
        return _err("UNAUTHORIZED", "forbidden: tenant is not active", tenant_status=tenant.get("status"))

    # Authenticate: require api_key belonging to tenant and active
    caller_key = _resolve_api_key_for_tenant(api_key, tenant)
    if caller_key is None:
        _log_tool_call("failed", http_status=401, api_key_id=None, error_code="AUTH_FAILED", error_message="invalid or unauthorized api_key for tenant", billed_units=1)
        _save("tool_calls.json", tool_calls)
        _save("usage_rollups.json", usage_rollups)
        return _err("UNAUTHORIZED", "invalid or unauthorized api_key")

    # Quota / rate limits enforcement (tenant daily/monthly + api key per minute)
    dt_now = datetime.datetime.utcnow()
    minute_ws = _floor_window(dt_now, "minute")
    day_ws = _floor_window(dt_now, "day")
    month_ws = _floor_window(dt_now, "month")

    # api key per-minute
    per_min_limit = int(caller_key.get("requests_per_minute_limit") or 0)
    if per_min_limit >= 0:
        current_minute = _count_window_requests(tenant_id, caller_key.get("id"), "minute", minute_ws)
        if current_minute >= per_min_limit:
            _log_tool_call("rate_limited", http_status=429, api_key_id=caller_key.get("id"), error_code="RATE_LIMIT", error_message="api key per-minute limit reached", billed_units=1)
            # increment dedicated rollups for api-key aggregate too
            r = _upsert_rollup(tenant_id, caller_key.get("id"), None, "minute", minute_ws)
            r["requests_count"] += 1
            r["rate_limited_count"] += 1
            r["billed_units"] += 1
            r["updated_at"] = now
            _save("tool_calls.json", tool_calls)
            _save("usage_rollups.json", usage_rollups)
            return _err("RATE_LIMIT", "api key per-minute limit reached")

    # tenant daily/monthly quotas
    daily_quota = int(tenant.get("daily_request_quota") or 0)
    monthly_quota = int(tenant.get("monthly_request_quota") or 0)
    day_count = _count_window_requests(tenant_id, None, "day", day_ws)
    month_count = _count_window_requests(tenant_id, None, "month", month_ws)
    if (daily_quota >= 0 and day_count >= daily_quota) or (monthly_quota >= 0 and month_count >= monthly_quota):
        _log_tool_call("rate_limited", http_status=429, api_key_id=caller_key.get("id"), error_code="QUOTA_EXCEEDED", error_message="tenant quota exceeded", billed_units=1)
        _save("tool_calls.json", tool_calls)
        _save("usage_rollups.json", usage_rollups)
        return _err("QUOTA_EXCEEDED", "tenant quota exceeded", daily_used=day_count, daily_quota=daily_quota, monthly_used=month_count, monthly_quota=monthly_quota)

    # Uniqueness constraint: unique(tenant_id, label)
    for pk in provider_keys:
        if pk.get("tenant_id") == tenant_id and pk.get("label") == label:
            _log_tool_call("failed", http_status=409, api_key_id=caller_key.get("id"), error_code="CONFLICT", error_message="label already exists for tenant", billed_units=1)
            _save("tool_calls.json", tool_calls)
            _save("usage_rollups.json", usage_rollups)
            return _err("CONFLICT", "label already exists for tenant", tenant_id=tenant_id, label=label)

    # Create record; "encrypt" provider_key (offline) using one-way wrapped format; never return plaintext
    salt = secrets.token_hex(8)
    digest = hashlib.sha256((salt + ":" + provider_key).encode("utf-8")).hexdigest()
    ciphertext = f"enc_v1:{salt}:{digest}"

    pk_row = {
        "id": _new_id("apk"),
        "tenant_id": tenant_id,
        "label": label.strip(),
        "provider_key_ciphertext": ciphertext,
        "status": status_param,
        "weight": int(weight_val),
        "created_at": now,
        "updated_at": now
    }
    provider_keys.append(pk_row)

    # Mark api key last_used_at on success path
    caller_key["last_used_at"] = now
    caller_key["updated_at"] = now

    _log_tool_call(
        "succeeded",
        http_status=201,
        api_key_id=caller_key.get("id"),
        provider_key_id=pk_row["id"],
        response_body={
            "id": pk_row["id"],
            "tenant_id": pk_row["tenant_id"],
            "label": pk_row["label"],
            "status": pk_row["status"],
            "weight": pk_row["weight"],
            "created_at": pk_row["created_at"],
            "updated_at": pk_row["updated_at"]
        },
        billed_units=1
    )

    _save("amap_provider_keys.json", provider_keys)
    _save("api_keys.json", api_keys)
    _save("tool_calls.json", tool_calls)
    _save("usage_rollups.json", usage_rollups)

    return {
        "amap_provider_key": {
            "id": pk_row["id"],
            "tenant_id": pk_row["tenant_id"],
            "label": pk_row["label"],
            "status": pk_row["status"],
            "weight": pk_row["weight"],
            "created_at": pk_row["created_at"],
            "updated_at": pk_row["updated_at"]
        }
    }

def admin_amap_provider_keys_update(mcp_session_id, api_key, id, label=None, provider_key=None, weight=None, status=None, **_extra):
    import json, os, datetime, time, hashlib, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0086000" if __import__("os").path.isdir("./environment_mix/0086000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"
    tool_name = "admin_amap_provider_keys_update"

    # ---- validate inputs ----
    if not isinstance(mcp_session_id, str) or not mcp_session_id.strip():
        return _err("VALIDATION_ERROR", "mcp_session_id must be a non-empty string")
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if label is not None and (not isinstance(label, str) or not label.strip()):
        return _err("VALIDATION_ERROR", "label must be a non-empty string when provided")
    if provider_key is not None and (not isinstance(provider_key, str) or not provider_key.strip()):
        return _err("VALIDATION_ERROR", "provider_key must be a non-empty string when provided")
    if weight is not None and (not isinstance(weight, int) or weight < 0):
        return _err("VALIDATION_ERROR", "weight must be an integer >= 0 when provided")
    if status is not None and status not in ("active", "disabled"):
        return _err("VALIDATION_ERROR", "status must be one of: active, disabled")

    tenants = _load("tenants.json")
    api_keys = _load("api_keys.json")
    provider_keys = _load("amap_provider_keys.json")
    usage_rollups = _load("usage_rollups.json")

    def _isoz(dt):
        return dt.replace(microsecond=0).isoformat() + "Z"

    def _floor(dt, gran):
        if gran == "minute":
            return dt.replace(second=0, microsecond=0)
        if gran == "hour":
            return dt.replace(minute=0, second=0, microsecond=0)
        if gran == "day":
            return dt.replace(hour=0, minute=0, second=0, microsecond=0)
        if gran == "month":
            return dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        return dt.replace(second=0, microsecond=0)

    def _gen_id(prefix):
        seed = f"{prefix}_{now_dt.isoformat()}_{os.getpid()}_{time.time_ns()}_{secrets.token_hex(4)}"
        suf = hashlib.sha1(seed.encode("utf-8")).hexdigest()[:24]
        return f"{prefix}_{suf}"

    def _find_api_key_row(api_key_value):
        for r in api_keys:
            if r.get("id") == api_key_value:
                return r
        for r in api_keys:
            kp = r.get("key_prefix")
            if isinstance(kp, str) and api_key_value.startswith(kp):
                return r
        return None

    def _ensure_rollup(tenant_id, api_key_id, tool, gran, window_start_iso):
        for r in usage_rollups:
            if (
                r.get("tenant_id") == tenant_id
                and r.get("api_key_id") == api_key_id
                and r.get("tool_name") == tool
                and r.get("window_granularity") == gran
                and r.get("window_start") == window_start_iso
            ):
                return r
        r = {
            "id": _gen_id("amap_usa"),
            "tenant_id": tenant_id,
            "api_key_id": api_key_id,
            "tool_name": tool,
            "window_start": window_start_iso,
            "window_granularity": gran,
            "requests_count": 0,
            "success_count": 0,
            "error_count": 0,
            "rate_limited_count": 0,
            "billed_units": 0,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        usage_rollups.append(r)
        return r

    def _encrypt_placeholder(plaintext):
        # Offline datastore: store a reversible placeholder is not required; keep ciphertext-like blob.
        salt = secrets.token_hex(8)
        h = hashlib.sha256((salt + ":" + plaintext).encode("utf-8")).hexdigest()
        return f"enc_v1:{salt}:{h}"

    def _unique_label_ok(tenant_id, new_label, self_id):
        if new_label is None:
            return True
        for r in provider_keys:
            if r.get("tenant_id") == tenant_id and r.get("label") == new_label and r.get("id") != self_id:
                return False
        return True

    # ---- auth/context ----
    ak = _find_api_key_row(api_key.strip())
    if not ak or ak.get("status") != "active":
        return _err("UNAUTHORIZED", "api_key is missing, inactive, or not recognized")

    tenant_id = ak.get("tenant_id")
    tenant = None
    for t in tenants:
        if t.get("id") == tenant_id:
            tenant = t
            break
    if not tenant:
        return _err("UNAUTHORIZED", "api_key has no valid tenant context", api_key_id=ak.get("id"), tenant_id=tenant_id)

    if tenant.get("status") != "active":
        # tool says FORBIDDEN; available codes list doesn't include it -> use UNAUTHORIZED to represent forbidden
        return _err("UNAUTHORIZED", "tenant is not active; updates are forbidden by business rule", tenant_id=tenant.get("id"), status=tenant.get("status"))

    # ---- find provider key record ----
    pk = None
    for r in provider_keys:
        if r.get("id") == id:
            pk = r
            break
    if not pk:
        return _err("NOT_FOUND", "amap_provider_key not found", id=id)

    # must belong to same tenant
    if pk.get("tenant_id") != tenant.get("id"):
        return _err("UNAUTHORIZED", "api_key is not authorized to manage this provider key", id=id, tenant_id=pk.get("tenant_id"))

    # ---- enforce constraints / lifecycle ----
    if label is not None and not _unique_label_ok(tenant.get("id"), label.strip(), id):
        return _err("CONFLICT", "unique(tenant_id, label) violated", tenant_id=tenant.get("id"), label=label.strip())

    if status is not None:
        cur = pk.get("status")
        transitions = {"active": ["disabled"], "disabled": ["active"]}
        if cur not in transitions:
            return _err("CONFLICT", "current provider key status is invalid", id=id, current_status=cur)
        if status != cur and status not in transitions[cur]:
            return _err("INVALID_TRANSITION", "illegal status transition for amap_provider_keys", id=id, from_status=cur, to_status=status)

    # ---- apply mutation (must have effect) ----
    changed = False
    if label is not None:
        v = label.strip()
        if pk.get("label") != v:
            pk["label"] = v
            changed = True
    if weight is not None:
        if int(pk.get("weight") or 0) != weight:
            pk["weight"] = weight
            changed = True
    if status is not None:
        if pk.get("status") != status:
            pk["status"] = status
            changed = True
    if provider_key is not None:
        # rotate key (store ciphertext placeholder), do not return plaintext
        pk["provider_key_ciphertext"] = _encrypt_placeholder(provider_key.strip())
        changed = True

    if not changed:
        # idempotent: return current row, but still record usage.
        pass

    pk["updated_at"] = now_iso

    # ---- observable dynamics (record usage) ----
    minute_ws = _isoz(_floor(now_dt, "minute"))
    hour_ws = _isoz(_floor(now_dt, "hour"))
    day_ws = _isoz(_floor(now_dt, "day"))
    month_ws = _isoz(_floor(now_dt, "month"))
    for (api_key_id, tool_dim) in ((None, None), (ak.get("id"), None)):
        for gran, ws in (("minute", minute_ws), ("hour", hour_ws), ("day", day_ws), ("month", month_ws)):
            rr = _ensure_rollup(tenant.get("id"), api_key_id, tool_dim, gran, ws)
            rr["requests_count"] = int(rr.get("requests_count") or 0) + 1
            rr["success_count"] = int(rr.get("success_count") or 0) + 1
            rr["updated_at"] = now_iso

    # ---- persist ----
    _save("amap_provider_keys.json", provider_keys)
    _save("usage_rollups.json", usage_rollups)

    duration_ms = max(0, int((time.time() - t0) * 1000))
    # Do not return provider_key_ciphertext? It's stored field; but response should not return plaintext.
    # Returning full row is acceptable; it does not include plaintext.
    return {
        "amap_provider_key": pk,
        "meta": {
            "updated_at": now_iso,
            "duration_ms": duration_ms,
            "tenant_id": tenant.get("id"),
            "api_key_id": ak.get("id"),
            "mcp_session_id": mcp_session_id,
        },
    }
